/** XML 转义 (v1.3.12 FILE-SEND: 文件名含特殊字符时防 XML 破坏) */
function escapeXml(s: string): string {
  return String(s ?? "").replace(/[<>&'"]/g, (c) => {
    switch (c) {
      case "<": return "&lt;";
      case ">": return "&gt;";
      case "&": return "&amp;";
      case "'": return "&apos;";
      case '"': return "&quot;";
      default: return c;
    }
  });
}

