    if (imageBase64) log.info(`[WPP v1.3.8 VIDEO-THUMB] auto-generated thumb for video (${videoUrlOrPath.slice(0, 60)})`);
  }
  // v1.3.22 SELF-MEDIA-OSS: 发视频前取 base64 → 上传 OSS (入库用 OSS 公网 URL)
