// ============ v1.1.17 恢复 (被 sendApp 删除时误删, 从备份恢复) ============

/**
 * v1.3.63 P2-CHUNKER-MARKDOWN (2026-08-13 老板反馈):真正的 markdown-aware chunker
 *   旧版注释说"按段落 (\n\n) 切"但实际用 `\n` 切 → 长段落(多行无空行)从中间切开
 *   新版:
 *   1. 优先按段落 (\n\n / \n\n+) 切
 *   2. 段落 > limit 时, 按行 (\n) 切
 *   3. 行 > limit 时, 硬切字符 (markdown 元素已破, 保 vendor 接受)
 *   4. 代码块 (```...```) 跨 chunk 不切断 (关键! 否则渲染坏)
 *   5. 表格行 (|...|) 跨 chunk 不切断
 *   6. 列表项 (- / * / 数字.) 保持完整
 */
/**
 * v1.3.63 P2-CHUNKER-MARKDOWN + P1-2/P2-1/P2-2 fix (2026-08-14 审阅):
 *   - P1-2: 巨型代码块单 chunk 超限 → 加 CODE_BLOCK_HARD_CAP 强制切分
 *   - P2-1: 代码块内含空行 → 围栏被段级切分拆断 → 切段前扫围栏跳过块内空行
 *   - P2-2: hardSplitLine 按 UTF-16 码元切会切断 emoji/生僻字 → codePointAt 对齐
 */
export function chunkMarkdown(text: string, limit: number): string[] {
  if (text.length <= limit) return [text];

  const out: string[] = [];
  let current = "";
  let inCodeBlock = false;

  // P2-1: 扫整个文本跟踪代码块围栏状态, 段级切分 (空行) 跳过块内空行
  const blocks: string[] = [];
  let buf = "";
  for (const line of text.split("\n")) {
    if (/^\s*```/.test(line)) inCodeBlock = !inCodeBlock;
    const isBlank = /^\s*$/.test(line);
    // 块内空行: 仍记录该行 (保留内容), 但不作为段落边界
    if (isBlank && !inCodeBlock) {
      blocks.push(buf); buf = "";
    } else {
      buf = buf ? `${buf}\n${line}` : line;
    }
  }
  if (buf) blocks.push(buf);
  const paragraphs = blocks.map((b) => b.trim()).filter(Boolean);

  for (const para of paragraphs) {
    // 段落 ≤ limit
    if (para.length <= limit) {
      // 当前 chunk 加这个段落会不会超? (留 2 字符给 \n\n 分隔)
      if (current.length + para.length + 2 > limit) {
        if (current) out.push(current);
        current = para;
      } else {
        current = current ? `${current}\n\n${para}` : para;
      }
      continue;
    }

    // 段落 > limit → 先 flush current, 切这个长段
    if (current) { out.push(current); current = ""; }
    out.push(...chunkLongParagraph(para, limit));
  }

  if (current) out.push(current);
  return out;
}

/**
 * v1.3.63 P2-CHUNKER-MARKDOWN + P1-2: 切长段落 (单段 > limit)
 * - 保护 ``` 代码块 (跨 chunk 不切断, 但超 CODE_BLOCK_HARD_CAP 强制切防 vendor 截断)
 * - 保护 | 表格行
 * - 单行超 limit 硬切字符
 */
const CODE_BLOCK_HARD_CAP = 2; // 代码块允许超过 limit 的倍数, 超则强制切分
function chunkLongParagraph(text: string, limit: number): string[] {
  const lines = text.split("\n");
  const out: string[] = [];
  let current = "";
  let inCodeBlock = false;

  for (const line of lines) {
    // 跟踪代码块状态: ``` 开头切换
    if (/^```/.test(line)) inCodeBlock = !inCodeBlock;

    // 单行超 limit → 硬切
    if (line.length > limit) {
      if (current) { out.push(current); current = ""; }
      out.push(...hardSplitLine(line, limit));
      continue;
    }

    // 当前 chunk 加这一行会不会超?
    const separator = current ? "\n" : "";
    const wouldExceed = current.length + separator.length + line.length > limit;
    // 代码块中: 超限但未达硬 cap → 推迟切分 (优先保持代码块完整)
    // 但加这行会超硬 cap → 强制切 (P1-2, 保证单 chunk ≤ limit*2, 防超 vendor 限)
    if (inCodeBlock && current.length + separator.length + line.length > limit * CODE_BLOCK_HARD_CAP) {
      out.push(current);
      current = line;
      continue;
    }
    if (wouldExceed && inCodeBlock) {
      current += `${separator}${line}`;
      continue;
    }
    if (wouldExceed) {
      // 普通超限 → 切: flush current, 重新开始
      out.push(current);
      current = line;
    } else {
      current = current ? `${current}${separator}${line}` : line;
    }
  }

  if (current) out.push(current);
  return out;
}

/**
 * v1.3.63 P2-CHUNKER-MARKDOWN + P2-2 fix: 硬切单行 (单行 > limit)
 * 按 codePointAt 对齐切 (不切断 emoji/生僻字代理对), 每段 ≤ limit 字符
 */
function hardSplitLine(line: string, limit: number): string[] {
  const out: string[] = [];
  let start = 0;
  while (start < line.length) {
    let end = Math.min(start + limit, line.length);
    // 若切点落在高代理位 (星面字符前半), 后移一位避免切断代理对
    const ch = line.charCodeAt(end - 1);
    if (ch >= 0xd800 && ch <= 0xdbff && end < line.length) end -= 1;
    out.push(line.slice(start, end));
    start = end;
  }
  return out;
}

/** normalize payload before sending (频道唯一 stub — 后续可加更多转换) */
export function normalizePayload(text: string): string {
  return text.trim();
}

/** chunker 入口 */
export const chunker = (text: string) =>
  text.length <= TEXT_CHUNK_LIMIT ? [text] : chunkMarkdown(text, TEXT_CHUNK_LIMIT);

// src/dispatch/media-oss.ts - v1.3.22 SELF-MEDIA-OSS
// 自己发送的媒体消息 (图/视频/语音) 上传 OSS, 入库 content 用 OSS 公网 URL (老板拍板, 参考 gewe downloadAndUploadToOss)。
// 复用 media-enrich 的 OSS 配置 (~/.openclaw/credentials/oss-credentials.json) + ossutil 上传范式。
// 失败降级: 上传失败不阻塞发送 (返回 null, 入库仍用源 URL)。

import { readFileSync } from "node:fs";
import { writeFile, mkdtemp, rm } from "node:fs/promises";
import { join } from "node:path";
import os from "node:os";
import crypto from "node:crypto";
import { execAsync } from "../util/exec.js";
import { logObj as log, formatErr } from "../core/logger.js";
import { buildOssKey } from "../inbound/media-enrich/shared.js";

const OSS_CREDENTIALS_PATH =
  process.env.OSS_CREDENTIALS_PATH ||
  join(os.homedir(), ".openclaw", "credentials", "oss-credentials.json");

interface OssConfig {
  accessKeyId: string;
  accessKeySecret: string;
  bucket: string;
  endpoint: string;
}

function loadOssConfig(credentialsPath?: string): OssConfig | null {
  // v1.3.22: 支持运行时传 credentialsPath (测试注入; 生产默认 OSS_CREDENTIALS_PATH)
  const p = credentialsPath ?? process.env.OSS_CREDENTIALS_PATH ?? OSS_CREDENTIALS_PATH;
  try {
    const raw = readFileSync(p, "utf8");
    const d = JSON.parse(raw) as Partial<OssConfig>;
    if (!d.accessKeyId || !d.accessKeySecret || !d.bucket) return null;
    return {
      accessKeyId: d.accessKeyId,
      accessKeySecret: d.accessKeySecret,
      bucket: d.bucket,
      endpoint: d.endpoint || "oss-cn-hangzhou.aliyuncs.com",
    };
  } catch {
    return null;
  }
}

/**
 * 上传 buffer 到 OSS (wpp/v1/<type>/<md5>.<ext>), 返回公网 URL。
 * 失败返回 null (降级, 不阻塞发送)。
 */
export async function uploadMediaToOss(
  buffer: Buffer,
  type: "image" | "video" | "voice",
  ext: string,
  accountId: string = "default",
  credentialsPath?: string,
): Promise<string | null> {
  try {
    const oss = loadOssConfig(credentialsPath);
    if (!oss) return null;
    const md5 = crypto.createHash("md5").update(buffer).digest("hex");
    // v1.3.35 OSS-STRUCTURE: 新格式 wpp/{account}/{type}/{date}/{md5}.{ext}
    // v1.3.56 MULTI-ACCOUNT: accountId 用真实账号 (防多账号媒体路径冲突互相覆盖)
    const ossKey = buildOssKey(accountId, `${type}s`, `${md5}.${ext}`);
    const tmpDir = await mkdtemp(join(os.tmpdir(), "wpp-oss-"));
    const tmpPath = join(tmpDir, `media.${ext}`);
    try {
      await writeFile(tmpPath, buffer);
      // ossutil cp (60s 超时 + 3 重试, 同 media-enrich 范式)
      let lastErr: Awaited<ReturnType<typeof execAsync>> | undefined;
      for (let attempt = 1; attempt <= 3; attempt++) {
        const r = await execAsync(
          "ossutil",
          ["cp", tmpPath, `oss://${oss.bucket}/${ossKey}`, "--endpoint", oss.endpoint, "-f"],
          { timeoutMs: 60_000 },
        );
        if (r.code === 0) {
          const url = `https://${oss.bucket}.${oss.endpoint}/${ossKey}`;
          log.info(`[WPP v1.3.22 SELF-MEDIA-OSS] uploaded ${type} → ${url} (${buffer.length} bytes)`);
          return url;
        }
        lastErr = r;
        log.warn(`[WPP v1.3.22 SELF-MEDIA-OSS] ossutil attempt ${attempt}/3 failed code=${r.code}`);
        if (attempt < 3) await new Promise((res) => setTimeout(res, 1000 * attempt));
      }
      throw new Error(
        `ossutil failed after 3 retries (last code=${lastErr?.code}): ${((lastErr?.stderr ?? lastErr?.stdout) ?? "").slice(0, 120)}`,
      );
    } finally {
      await rm(tmpDir, { recursive: true, force: true });
    }
  } catch (e) {
    log.warn(`[WPP v1.3.22 SELF-MEDIA-OSS] upload ${type} failed (non-fatal, keep source URL): ${formatErr(e)}`);
    return null;
  }
}

// util/exec.ts - spawn-based async exec wrapper
// 仿 本项目/src/util/exec.ts 范式
// 关键: never block main thread, no shell, SIGKILL on timeout

import { spawn } from "node:child_process";

export interface ExecOptions {
  cwd?: string;
  env?: NodeJS.ProcessEnv;
  timeoutMs?: number;
  /** stdin mode (default "ignore") */
  stdinMode?: "ignore" | "close" | "pipe";
}

export interface ExecResult {
  code: number | null;
  signal: NodeJS.Signals | null;
  stdout: string;
  stderr: string;
  /** 总耗时 (ms) */
  latencyMs: number;
}

/**
 * execAsync(cmd, args[], opts?) — never throws on non-zero exit.
 * - spawn (no shell) 防命令注入 (vendor 推 binary 时含 shell 元字符会爆)
 * - 默认 timeout 30s, SIGKILL 兜底
 * - 默认 stdin "ignore" (防 stdin hang)
 *
 * 与 child_process.exec 不一样: 我们返回完整 stdout/stderr 不 throw;
 * 调用方按 code 判断是否成功
 */
export function execAsync(
  command: string,
  args: string[] = [],
  opts: ExecOptions = {},
): Promise<ExecResult> {
  const timeoutMs = opts.timeoutMs ?? 30_000;
  const started = Date.now();

  return new Promise<ExecResult>((resolve) => {
    const child = spawn(command, args, {
      cwd: opts.cwd,
      env: opts.env,
      stdio: [
        opts.stdinMode === "pipe" ? "pipe" : "ignore",
        "pipe",
        "pipe",
      ],
      // don't open shell
      shell: false,
      windowsHide: true,
    });

    let stdout = "";
    let stderr = "";
    let killed = false;

    const timer = setTimeout(() => {
      killed = true;
      try {
        child.kill("SIGKILL");
      } catch {
        /* already dead */
      }
    }, timeoutMs);

    if (child.stdout) {
      child.stdout.setEncoding("utf8");
      child.stdout.on("data", (chunk) => {
        stdout += chunk;
      });
    }
    if (child.stderr) {
      child.stderr.setEncoding("utf8");
      child.stderr.on("data", (chunk) => {
        stderr += chunk;
      });
    }

    child.on("error", (err) => {
      clearTimeout(timer);
      if (killed) {
        resolve({ code: null, signal: "SIGKILL", stdout, stderr, latencyMs: Date.now() - started });
      } else {
        resolve({
          code: null,
          signal: null,
          stdout,
          stderr: stderr ? stderr + (err.message ? `\n${err.message}` : "") : err.message,
          latencyMs: Date.now() - started,
        });
      }
    });

    child.on("close", (code, signal) => {
      clearTimeout(timer);
      resolve({
        code: killed ? null : code,
        signal: killed ? "SIGKILL" : signal,
        stdout,
        stderr,
        latencyMs: Date.now() - started,
      });
    });
  });
}

// src/inbound/media-enrich/shared.ts - 媒体 enrich 共享基础设施 (OSS + vendor 下载 helper)
// 从 media-enrich.ts v1.3.26 拆分 (2026-08-10, P3-2): 仅搬运, 不优化

import { logObj as log } from "../../core/logger.js";
import { execAsync } from "../../util/exec.js";
import type { WppAccountCtx } from "../../send/factory.js";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import crypto from "node:crypto";

const OSS_CREDENTIALS_PATH =
  process.env.OSS_CREDENTIALS_PATH ||
  path.join(os.homedir(), ".openclaw", "credentials", "oss-credentials.json");

/**
 * v1.3.34 OSS-STRUCTURE (2026-08-11 老板拍板): OSS key 统一格式 `wpp/{account}/{type}/{date}/{filename}`
 *   账号隔离 + 文件类型 + 日期归档 (方便检索/清理)。
 *   @param accountId 账号 id (e.g. "default")
 *   @param type 文件类型 (images/videos/voices/files)
 *   @param filename 文件名 (含扩展名)
 *   @returns OSS key (e.g. "wpp/default/images/2026-08-11/xxx.jpg")
 */
export function buildOssKey(accountId: string, type: string, filename: string): string {
  const date = new Date().toISOString().slice(0, 10); // YYYY-MM-DD
  return `wpp/${accountId || "default"}/${type}/${date}/${filename}`;
}

/**
 * v1.3.63 P3 (2026-08-14 审阅): md5 文件名净化.
 *   v0 schema md5 是 hex digest, 但 v1 schema 的 md5 是自由字符串 → 直接拼进 OSS key 可污染路径/上下文.
 *   只允许 hex 字符串, 否则 fallback 随机 hex (不信任自由字符串).
 */
export function sanitizeFilenamePart(input: unknown, fallbackLen = 16): string {
  const s = typeof input === "string" ? input : "";
  if (/^[a-f0-9]{8,64}$/i.test(s)) return s.toLowerCase();
  return crypto.randomBytes(Math.ceil(fallbackLen / 2)).toString("hex").slice(0, fallbackLen);
}

interface OssConfig {
  accessKeyId: string;
  accessKeySecret: string;
  bucket: string;
  endpoint: string;
}

export function loadOssConfig(): OssConfig | null {
  try {
    const raw = fs.readFileSync(OSS_CREDENTIALS_PATH, "utf8");
    const d = JSON.parse(raw) as Partial<OssConfig>;
    if (!d.accessKeyId || !d.accessKeySecret || !d.bucket) return null;
    return {
      accessKeyId: d.accessKeyId,
      accessKeySecret: d.accessKeySecret,
      bucket: d.bucket,
      endpoint: d.endpoint || "oss-cn-hangzhou.aliyuncs.com",
    };
  } catch {
    return null;
  }
}
/**
 * ossutil cp 上传本地文件到 OSS, 返回公网 URL。
 * 60s 超时 + 3 次重试 (OSS 临时网络抖动会 SIGKILL 超时进程 → enrich 失败)
 */
export async function uploadToOss(
  oss: OssConfig,
  localPath: string,
  ossKey: string,
): Promise<string> {
  let lastErr: Awaited<ReturnType<typeof execAsync>> | undefined;
  for (let attempt = 1; attempt <= 3; attempt++) {
    const r = await execAsync(
      "ossutil",
      [
        "cp",
        localPath,
        `oss://${oss.bucket}/${ossKey}`,
        "--endpoint",
        oss.endpoint,
        "-f",
      ],
      { timeoutMs: 60_000 },
    );
    if (r.code === 0) {
      // 公网 URL: https://{bucket}.{endpoint}/{key}
      return `https://${oss.bucket}.${oss.endpoint}/${ossKey}`;
    }
    lastErr = r;
    log.warn(
      `[WPP v1.3.74] ossutil cp attempt ${attempt}/3 failed (code=${r.code} signal=${r.signal ?? "none"}) stderr=${(r.stderr || r.stdout).slice(0, 100)}`,
    );
    if (attempt < 3) await new Promise((r) => setTimeout(r, 1000 * attempt));
  }
  throw new Error(
    `ossutil cp failed after 3 retries (last code=${lastErr?.code} signal=${lastErr?.signal ?? "none"}): ${((lastErr?.stderr ?? lastErr?.stdout) ?? "").slice(0, 200)}`,
  );
}
/**
 * 调 vendor /Tools/CdnDownloadImage 下载图片 → base64 JPEG
 */
export async function downloadImageBase64(
  ctx: WppAccountCtx,
  aesKey: string,
  fileNo: string,
): Promise<string> {
  const { postWppJson } = await import("../../api/client.js");
  const { ctxToCallOpts } = await import("../../send/factory.js");
  const resp = await postWppJson<{ Image?: string }>(
    ctx.baseUrl,
    "/Tools/CdnDownloadImage",
    { fileAesKey: aesKey, fileNo },
    ctxToCallOpts(ctx),
  );
  const image = resp.Data?.Image;
  if (!image) {
    throw new Error(
      `CdnDownloadImage missing Image: code=${resp.Code} value=${resp.CodeValue ?? ""}`,
    );
  }
  return image;
}
/**
 * v1.2.1 P2-fix: 公共 OSS 上传 (buffer → tmp → ossutil → 公网 URL)。
 * 复用 media-enrich 各处的 hash+safeName+upload 逻辑, 避免 6 处重复。
 */
export async function ossUploadBuffer(
  buf: Buffer,
  filename: string,
  prefix: string,
  opts?: { accountId?: string; type?: string },
): Promise<string> {
  const oss = loadOssConfig();
  if (!oss) throw new Error("oss credentials missing");
  const ext = (filename.match(/\.([a-zA-Z0-9]+)$/) || [])[1] || "bin";
  const tmpPath = path.join(os.tmpdir(), `wpp-upload-${crypto.randomBytes(6).toString("hex")}.${ext}`);
  try {
    fs.writeFileSync(tmpPath, buf);
    const hash = crypto.createHash("md5").update(filename).digest("hex").slice(0, 12);
    const safeName = filename.replace(/[^\w.\-]/g, "_");
    // v1.3.34 OSS-STRUCTURE: opts 提供 → 用新格式 wpp/{account}/{type}/{date}/{hash}-{safeName}
    //   否则兼容老 prefix 调用 (e.g. MCP 路径)
    const ossKey = opts?.accountId && opts?.type
      ? buildOssKey(opts.accountId, opts.type, `${hash}-${safeName}`)
      : `${prefix}/${hash}-${safeName}`;
    return await uploadToOss(oss, tmpPath, ossKey);
  } finally {
    try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
  }
}
export async function downloadByEndpoint(
  ctx: WppAccountCtx,
  endpoint: string,
  aesKey: string,
  fileNo: string,
  extraBody: Record<string, unknown> = {},
): Promise<string> {
  const { postWppJson } = await import("../../api/client.js");
  const { ctxToCallOpts } = await import("../../send/factory.js");
  const resp = await postWppJson<Record<string, unknown>>(
    ctx.baseUrl,
    endpoint,
    { aesKey, fileId: fileNo, ...extraBody },
    ctxToCallOpts(ctx),
  );
  const data = (resp.Data ?? {}) as Record<string, unknown>;
  const b64 =
    (typeof data.File === "string" && data.File) ||
    (typeof data.file === "string" && data.file) ||
    (typeof data.Video === "string" && data.Video) ||
    (typeof data.video === "string" && data.video) ||
    (typeof data.Voice === "string" && data.Voice) ||
    (typeof data.voice === "string" && data.voice) ||
    (typeof data.Buffer === "string" && data.Buffer) ||
    (typeof data.buffer === "string" && data.buffer) ||
    "";
  if (!b64) {
    throw new Error(
      `${endpoint} missing binary data: code=${resp.Code} value=${resp.CodeValue ?? ""}`,
    );
  }
  return b64;
}
