/**
 * 清洗群消息 content 的发送者 wxid 前缀
 * vendor 群消息 content 形如 "wxid_xxx:\n@bot 你好" (单 wxid + 冒号 + 换行)
 * 或 "senderNick:\n<content>" (昵称 + 冒号 + 换行) — refermsg.content 应只含正文
 */
export function stripGroupContentPrefix(content: string | undefined): string | undefined {
  if (!content) return content;
  // 形如 "wxid_xxx:\n..." 或 "gh_xxx:\n..." 或 "xxx@chatroom:\n..." (首行是 wxid + 冒号)
  const m = content.match(/^[a-zA-Z0-9_@:-]+:\n([\s\S]*)$/);
  if (m && m[1]) return m[1].trim();
  return content;
}

/**
 * 从 vendor 群消息 content 提取真实发送者 wxid (content 前缀 "wxid_xxx:\n")
 * 根因: business callback 的 FromUserName = 群 ID, 发送者 wxid 只在 content 首行前缀
 * 例: "wxid_sender:\n@bot 你好" → "wxid_sender"
 */
export function extractGroupSenderWxid(content: string | undefined): string | undefined {
  if (!content) return undefined;
  // 首行形如 "wxid_xxx:" (wxid 开头) → 提取 wxid
  const m = content.match(/^(wxid_[a-zA-Z0-9_]+|gh_[a-zA-Z0-9_]+|[a-zA-Z0-9_]+@chatroom):\n/);
  if (m && m[1]) return m[1];
  return undefined;
}

/**
 * 引用回复 (文本/图片通用):
 * - 从 DB 查被引用消息, 拿原文 content (图片=图片XML) + fromWxid 等
 * - 构造完整 refermsg → ShareLink 发送
 */
export async function quoteReply(params: QuoteReplyParams): Promise<{ ok: boolean; msg?: string; data?: unknown }> {
  const {
    toWxid, content, msgId, newMsgId, accountId,
    fromWxid, chatroomId, fromNickname, originalContent, createtime, innerType,
  } = params;
  const acct = accountId ?? "default";

  // displayname 兑底变量 (DB peer_name)
  let paramsFromNicknameFallback: string | undefined;

  // 参数 fromWxid 是群 ID (@chatroom 结尾) 时视为无效 → 置 undefined 走 DB 补全 (防 fromusr 永远是群ID)
  const paramFromWxidValid = fromWxid && !fromWxid.endsWith("@chatroom") ? fromWxid : undefined;

  // svrid 直接用 inbound newMsgId (vendor 全局唯一)
  let svrid = newMsgId || msgId || "";
  let dbFromWxid: string | undefined = paramFromWxidValid;
  let dbChatroomId: string | undefined = chatroomId;
  let dbOriginalContent: string | undefined = stripGroupContentPrefix(originalContent);
  let dbCreatetime: number | undefined = createtime;
  let dbInnerType: number | undefined = innerType;
  try {
    // v1.3.18 P1-核心2: 引用查询传 direction: "any" (被引用消息可能是 bot  outbound)
    const rec = await getMessageByMsgIdOrNewId(msgId, newMsgId, acct, { direction: "any" });
    if (rec) {
      const mappedSvrid = await resolveQuoteSvrid(msgId, newMsgId, rec.content ?? undefined, acct);
      if (mappedSvrid && mappedSvrid !== msgId) {
        svrid = mappedSvrid;
      }
      // 发送者 wxid 提取: 参数优先 → raw_payload sender → content 前缀 wxid → (非群) peer_id
      // (business callback FromUserName = 群 ID, 发送者只在 content 前缀)
      const raw = (rec.raw_payload ?? {}) as Record<string, unknown>;
      const rawSenderId =
        (typeof raw.sender_id === "string" ? raw.sender_id : undefined) ??
        (typeof raw.fromUser === "string" ? raw.fromUser : undefined) ??
        (typeof raw.FromWxid === "string" ? raw.FromWxid : undefined) ??
        (typeof raw.fromWxid === "string" ? raw.fromWxid : undefined);
      const isGroupRec = rec.peer_kind === "group";
      // 真实发送者: 参数优先 → raw_payload sender → content 前缀 wxid → (非群) peer_id
      dbFromWxid =
        dbFromWxid ??
        rawSenderId ??
        extractGroupSenderWxid(rec.content ?? undefined) ??
        (isGroupRec ? undefined : (rec.peer_id ?? undefined));
      // 会话 wxid: 群 = chat_id, 私聊 = peer_id (对方 wxid)
      dbChatroomId = dbChatroomId ?? (isGroupRec ? (rec.chat_id ?? undefined) : (rec.peer_id ?? undefined));
      dbOriginalContent = dbOriginalContent ?? stripGroupContentPrefix(rec.content ?? undefined);
      dbCreatetime = dbCreatetime ?? rec.ts;
      dbInnerType = dbInnerType ?? (rec.msg_type ? parseInt(rec.msg_type, 10) : undefined);
      // displayname 兑底: 参数 → peer_name
      if (!fromNickname && rec.peer_name) {
        paramsFromNicknameFallback = rec.peer_name;
      }
    }
  } catch {
    // DB 查询失败不阻塞
  }

  // displayname 优先级: 参数 fromNickname > DB peer_name > 通讯录昵称查询
  const displayName =
    fromNickname ||
    paramsFromNicknameFallback ||
    (await resolveDisplayName(acct, dbFromWxid));

  const quote = {
    svrid,
    fromusr: dbFromWxid,
    chatusr: dbChatroomId ?? toWxid,
    displayname: displayName,
    content: dbOriginalContent,
    createtime: dbCreatetime,
    innerType: dbInnerType,
  };

  // v1.3.33 GROUP-MENTION-REPLY (老板拍板 2026-08-11): 群聊引用回复时加 @被回复人昵称 (gewe 范式)
  const finalContent = buildGroupMentionPrefix(toWxid, content, displayName, quote.fromusr);
  const xml = buildQuoteReplyXml(finalContent, quote);
  const state = getDefaultAccountRegistry().get(acct);
  const cfg = state?.config;
  info(`[WPP v1.2.0 QUOTE-TITLE-FIX] quoteReply ShareLink type=57: to=${toWxid} svrid=${svrid} (title=AI reply + svrid+fromusr refermsg)`);
  info(`[WPP v1.2.0 QUOTE-TITLE-FIX] quoteReply XML (first 800 chars): ${xml.slice(0, 800).replace(/\n/g, "\\n")}`);
  info(`[WPP v1.2.0 QUOTE-TITLE-FIX] quoteReply XML totalLen=${xml.length}`);
  // vendor /Msg/Quote 永久 ret=-2 不可用 → 走 /Msg/ShareLink + Type=5 + 自构造 XML (gewe 范式)
  const resp = await postWppJson(cfg?.apiBaseUrl ?? "", "/Msg/ShareLink", {
    ToWxid: toWxid,
    Type: 5,
    Xml: xml,
  }, {
    tokenKey: cfg?.tokenKey ?? "",
    authcode: cfg?.authcode ?? "",
    timeoutMs: 30000,
  });
  const d = (resp.Data ?? {}) as { BaseResponse?: { ret?: number; errMsg?: unknown }; msgId?: number; newMsgId?: number; type?: number };
  const baseRespRet = d.BaseResponse?.ret;
  info(`[WPP v1.2.0 REVERT] vendor resp: Code=${resp.Code} ret=${baseRespRet} msgId=${d.msgId ?? 0} newMsgId=${d.newMsgId ?? 0} type=${d.type ?? 0}`);
  // 判据陷阱: Code=0 只是 HTTP 200, 真正成功看 Data.BaseResponse.ret === 0 (msgId=0 时 Code=0 不代表成功)
  // v1.3.57 P2-3 (2026-08-13 交付审阅): Code=200 也视为成功 (与 outbound.ts isSendOk 对齐)
  const ok = (resp.Code === 0 || resp.Code === 200) && (baseRespRet === 0 || baseRespRet === undefined);
  if (ok) await persistQuoteReply(acct, toWxid, content, resp);
  return {
    ok,
    msg: ok ? "引用回复已发送" : `发送失败 Code=${resp.Code} ${resp.CodeValue ?? ""}`,
    data: resp.Data,
  };
}

// src/send/quote-xml.ts - 引用回复 XML 构造
// 关键: appmsg type=57 客户端主气泡读 <title> 字段, <des> 在 type=57 被吞。
// 因此 title = AI 回复文字 (gewe 工作基线), 不能放被引用人 displayname (否则只显示 refermsg 预览)。

export interface QuoteSource {
  /** 被引用消息的 svrid (= inbound NewMsgId, vendor 全局唯一) */
  svrid: string;
  /** 被引用消息的发送者 wxid */
  fromusr?: string;
  /** 被引用消息的所属会话 wxid (群聊时 = 群id, 私聊时 = 对方 wxid) */
  chatusr?: string;
  /** 被引用消息的发送者昵称 (用于引用块展示) */
  displayname?: string;
  /** 被引用消息的原文 (文本=原文, 图片=图片 XML) */
  content?: string;
  /** 被引用消息的创建时间 (秒) */
  createtime?: number;
  /** 被引用消息的类型 (1=text 3=image 34=voice 43=video 47=emoji 49=app) */
  innerType?: number;
}

function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

/**
 * 引用回复 XML: title=des=AI 回复 (双填保险, 老客户端可能读 des), type=57, refermsg=svrid+fromusr
 */
export function buildQuoteReplyXml(
  replyContent: string,
  quote: QuoteSource,
  opts?: { innerType?: 57 | 49 },
): string {
  const innerType = opts?.innerType ?? 57;
  const reply = (replyContent || "引用回复").trim();
  const title = escapeXml(reply.slice(0, 500));
  const des = escapeXml(reply.slice(0, 500));

  // refermsg 极简化 (gewe 基线): 仅 svrid 客户端已能渲染; 加 fromusr 兼容老版本回查昵称
  const svrid = escapeXml(quote.svrid.trim());
  const fromusr = quote.fromusr ? escapeXml(quote.fromusr) : "";

  const refermsg = svrid
    ? `<refermsg>` +
      `<svrid>${svrid}</svrid>` +
      (fromusr ? `<fromusr>${fromusr}</fromusr>` : "") +
      `</refermsg>`
    : "";

  return `<appmsg><title>${title}</title><des>${des}</des><type>${innerType}</type>${refermsg}</appmsg>`;
}

// src/inbound/quote-svrid.ts - 引用消息 svrid 捕获 (v1.1.24)
// 2026-08-08 19:39 接总立验证成功: 真实 svrid (从引用消息 refermsg) + 完整图片 XML → 能定位 + 缩略图
// 核心: 微信 svrid 无法主动获取 (vendor 不提供), 只能从"别人引用该消息"的 refermsg.svrid 被动捕获
// 捕获后存 DB 映射 (md5 → svrid), AI 引用时优先查真实 svrid

import { parseQuoteXml } from "./parser/quote.js";
import { info, warn } from "../core/logger.js";
import { saveSvridMapping, getSvridByMd5 } from "../db.js";

/**
 * 从引用消息 content 里提取被引用图片的 md5
 * refermsg.content 是被引用消息原文 — 图片时含 <img ... md5="...">
 */
export function extractQuotedImgMd5(content: string | undefined): string | undefined {
  if (!content) return undefined;
  const m = content.match(/md5="([0-9a-f]{32})"/i);
  return m ? m[1] : undefined;
}

/**
 * 捕获引用消息的 svrid → 存 DB 映射
 * 被引用消息 (refermsg.content) 的 md5 → svrid 关联
 * @param msgContent 收到的引用消息完整 content (含 refermsg)
 * @param accountId 账号
 */
export async function captureQuoteSvrid(
  msgContent: string,
  accountId: string,
): Promise<{ svrid?: string; md5?: string; captured: boolean }> {
  if (!msgContent.includes("<refermsg")) {
    return { captured: false };
  }
  const parsed = parseQuoteXml(msgContent);
  if (!parsed?.msgId) {
    return { captured: false };
  }
  const svrid = parsed.msgId;
  // 被引用内容: 图片 → md5; 文本 → 无 md5
  const quotedContent = parsed.content;
  const md5 = extractQuotedImgMd5(quotedContent);

  try {
    // 存映射 (md5 → svrid); 文本消息 md5 为 null, 用 content hash 兜底
    await saveSvridMapping({
      account_id: accountId,
      svrid,
      msg_md5: md5 ?? null,
      // 被引用消息的 new_msg_id 可作关联线索 (如有)
      quoted_content_hash: quotedContent ? simpleHash(quotedContent.slice(0, 200)) : null,
      captured_at: Math.floor(Date.now() / 1000),
    });
    info(
      `[WPP v1.3.74] quote svrid captured: svrid=${svrid} md5=${md5 ?? "(text)"} (account=${accountId})`,
    );
    return { svrid, md5: md5 ?? undefined, captured: true };
  } catch (e) {
    warn(`[WPP v1.3.74] quote svrid capture failed (non-fatal): ${e instanceof Error ? e.message : String(e)}`);
    return { svrid, md5: md5 ?? undefined, captured: false };
  }
}

function simpleHash(s: string): string {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = (h << 5) - h + s.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(36);
}

/**
 * 查真实 svrid: 优先 md5 映射, fallback 被引用消息的 new_msg_id
 * @param msgId 被引用消息 msg_id (DB 查询)
 * @param newMsgId 被引用消息 new_msg_id
 * @param content 被引用消息 content (含 md5 的话)
 * @param accountId 账号
 */
export async function resolveQuoteSvrid(
  msgId: string,
  newMsgId: string | undefined,
  content: string | undefined,
  accountId: string,
): Promise<string> {
  const md5 = extractQuotedImgMd5(content);
  if (md5) {
    const svrid = await getSvridByMd5(md5, accountId);
    if (svrid) {
      info(`[WPP v1.3.74] svrid resolved via md5: ${svrid} (md5=${md5})`);
      return svrid;
    }
  }
  if (newMsgId) {
    return newMsgId;
  }
  return msgId;
}

// src/inbound/parser/quote.ts - 引用消息 <refermsg> XML 解析

import { safeMatch } from "../../core/safe-regex.js";

export interface QuoteRef {
  msgId: string;
  newMsgId?: string;
  fromWxid?: string;
  title?: string;
  type?: string;
  /** 被引用消息原文 (文本=原文, 图片=图片XML) */
  content?: string;
}

/** Parse `<refermsg type="..."><type>...</type><svrid>...</svrid>...</refermsg>` block */
export function parseQuoteXml(content: string): QuoteRef | null {
  if (!content || !content.includes("<refermsg")) return null;
  // 用 safeMatch 截断 4096 防恶意构造 XML 触发 ReDoS
  const block = safeMatch(/<refermsg\b[^>]*>([\s\S]*?)<\/refermsg>/, content);
  if (!block || block[1] === undefined) return null;
  const inner = block[1];

  const tag = (name: string): string | undefined => {
    const m = safeMatch(new RegExp(`<${name}>([\\s\\S]*?)<\\/${name}>`), inner, 2048);
    return m && m[1] ? m[1].trim() : undefined;
  };

  const result: QuoteRef = {
    type: tag("type"),
    msgId: tag("svrid") ?? tag("msgid") ?? "",
    // 真实结构是 <fromusr> (不是 fromusername)
    fromWxid: tag("fromusr") ?? tag("fromusername"),
    title: tag("displayname") ?? tag("title"),
    content: tag("content"),
  };
  if (!result.msgId) return null;
  return result;
}

/**
 * v1.3.5 QUOTE-REPLY-CONTEXT: 新版 vendor 引用走 raw_payload.reply_context (非 content <refermsg> XML)。
 * 结构: { msg_id: uint32, new_msg_id, svr_id, quote_content, msg_type, from_user_id, ... }
 * 提取被引用消息的定位字段 (msg_id 可能是被引用消息 local_id, svr_id 可能是当前消息自身)。
 */
export interface ReplyContextRef {
  /** vendor 内部 msg_id (uint32) — 可能是被引用消息 local_id */
  msgId?: number;
  newMsgId?: string;
  svrId?: string;
  /** 被引用内容文字 (图片消息则为描述) */
  quoteContent?: string;
  /** 被引用消息类型 (3=图片, 49=文件, 1=文本...) */
  msgType?: number;
  fromWxid?: string;
  chatroomId?: string;
}

/** 从 raw_payload 提取 reply_context 引用信息 (无则 null) */
export function extractReferencedFromReplyContext(raw: unknown): ReplyContextRef | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const rc = r.reply_context as Record<string, unknown> | undefined;
  if (!rc || typeof rc !== "object") return null;
  return {
    msgId: typeof rc.msg_id === "number" ? rc.msg_id : undefined,
    newMsgId: typeof rc.new_msg_id === "string" ? rc.new_msg_id : undefined,
    svrId: typeof rc.svr_id === "string" ? rc.svr_id : undefined,
    quoteContent: typeof rc.quote_content === "string" ? rc.quote_content : undefined,
    msgType: typeof rc.msg_type === "number" ? rc.msg_type : undefined,
    fromWxid: typeof rc.from_user_id === "string" ? rc.from_user_id : undefined,
    chatroomId: typeof rc.chat_user_id === "string" ? rc.chat_user_id : undefined,
  };
}

/**
 * v1.3.6 QUOTE-APP-REFERENCE: 新版 vendor 引用消息的**被引用信息在 app.reference** (category=quote),
 * 不在 reply_context! 结构:
 *   app: { category: "quote", reference: { new_msg_id, svr_id, msg_type, from_user_id, display_name } }
 * 实测: app.reference.new_msg_id 精确匹配 DB msg_id 列 → 定位被引用消息 (图/文件/文本)
 */
export interface AppReference {
  newMsgId?: string;
  svrId?: string;
  msgType?: number;
  fromWxid?: string;
  displayName?: string;
}

/** 从 raw_payload 提取 app.reference (category=quote 引用消息) 被引用信息 */
export function extractReferencedFromApp(raw: unknown): AppReference | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const app = r.app as Record<string, unknown> | undefined;
  if (!app || typeof app !== "object") return null;
  if (app.category !== "quote") return null;
  const ref = app.reference as Record<string, unknown> | undefined;
  if (!ref || typeof ref !== "object") return null;
  return {
    newMsgId: typeof ref.new_msg_id === "string" ? ref.new_msg_id : undefined,
    svrId: typeof ref.svr_id === "string" ? ref.svr_id : undefined,
    msgType: typeof ref.msg_type === "number" ? ref.msg_type : undefined,
    fromWxid: typeof ref.from_user_id === "string" ? ref.from_user_id : undefined,
    displayName: typeof ref.display_name === "string" ? ref.display_name : undefined,
  };
}

// src/core/safe-regex.ts - 灾难 regex 拦截 (gewe v3.1.0 A1 移植)
//
// 背景: 群接龙 title / 引用消息 XML 内容 / 群消息 nick prefix 都用 regex 解析
//   攻击面: 用户发送恶意构造字符串触发 ReDoS
//   历史教训: gewe v3.1.0 fullfix A1 实测 `(a+)+$` 1000 字符 hang 119s
//   风险模式: 嵌套量词 ((a+)+, (a*)*, (?:.+)+) / 灾难 alternation (a|a)+ / 嵌套捕获
//
// 防护策略:

/**
 * 检测正则是否包含灾难模式 (嵌套量词 / 灾难 alternation)
 * 启发式: 出现 (X+)+ / (X*)* / (?:X+)+ 等模式直接判灾难
 * 误判率 < 5%, 实际生产中几乎无合法 regex 用嵌套量词
 */
export function isCatastrophicRegex(pattern: string | RegExp): boolean {
  const src = typeof pattern === "string" ? pattern : pattern.source;
  // 灾难模式: 嵌套量词 (a+)+, (a*)*, (?:.+)+, (a+)*, (a|b)+
  if (/\((?:\?[:=!])?[^)]*[+*]\)[+*?]/.test(src)) return true;
  // 灾难 alternation: ([a-z]+|[0-9]+)+ 等
  if (/\([^)]*\|[^)]*\)[+*]/.test(src)) return true;
  // 多个连续量词: a++ / a*+ / a{1,}+
  if (/[+*]\+|[+*]\*|[+*]\{[0-9,]+\}\+/.test(src)) return true;
  // \w+\w+\w+ 等多连接 + 整体 + 灾难
  if (/\\[wWsSdD]\+.*\\?[wWsSdD]\+.*[+*]\)?\+/.test(src)) return true;
  return false;
}

/**
 * 安全的 String.match, 超长输入截断到 maxLen (默认 4096)
 * gewe v3.1.0 实测 4096 字符足够所有业务 XML
 */
export function safeMatch(
  pattern: RegExp,
  input: string,
  maxLen = 4096,
): RegExpMatchArray | null {
  const truncated = input.length > maxLen ? input.slice(0, maxLen) : input;
  return truncated.match(pattern);
}

/**
 * 安全 matchAll, 超长截断 + 单次执行 100ms 超时 (web 异步不能用 setTimeout 杀同步 regex, 但可在 worker 用)
 * 简单兜底: 截断 + 调用 matchAll
 */
export function safeMatchAll(
  pattern: RegExp,
  input: string,
  maxLen = 4096,
): RegExpStringIterator<RegExpMatchArray> {
  const truncated = input.length > maxLen ? input.slice(0, maxLen) : input;
  return truncated.matchAll(pattern);
}

/**
 * 替代现有 regex 调用的工厂: 检测到灾难模式 → 抛错 (开发期) 或用 safe fallback (生产期)
 * 调用方应该 try/catch 或检查返回值
 */
export function guardedRegex(pattern: RegExp, fallback: RegExp | null = null): RegExp {
  if (isCatastrophicRegex(pattern)) {
    if (fallback) return fallback;
    throw new Error(
      `catastrophic regex detected: ${pattern.source.slice(0, 80)} (嵌套量词/灾难 alternation). ` +
        `fix: 用非嵌套结构 (a+ → a*?) 或拆 regex`,
    );
  }
  return pattern;
}

// src/dispatch/reply-helpers.ts - quote reply + format helpers
// 仿 本项目/src/dispatch/reply-helpers.ts

import type { WppInboundMessage } from "../types.js";
import { parseQuoteXml } from "../inbound/parser/quote.js";

export function buildQuoteContext(msg: WppInboundMessage): string | null {
  // v1.1.21 QUOTE-FIX: 引用消息才注入 (非引用返回 null)
  if (!msg.content.includes("<refermsg")) return null;

  // 解析 refermsg 块 — 拿被引用内容 (文本原文 / 图片 XML) + 发送者
  const parsed = parseQuoteXml(msg.content);
  const sender = msg.fromNickname ?? msg.fromWxid;
  if (!parsed) {
    return `<quoted-sender>${sender}</quoted-sender>
<quoted-msgid>${msg.msgId}</quoted-msgid>`;
  }
  // 被引用内容: 文本直接显示, 图片显示类型提示
  const isImg = parsed.content?.includes("<img") ?? false;
  const refContent = isImg
    ? "(被引用内容是一张图片)"
    : (parsed.content && parsed.content.length > 0 ? parsed.content : parsed.title ?? "(未知内容)");
  return `<quoted-sender>${sender}</quoted-sender>
<quoted-msgid>${parsed.msgId}</quoted-msgid>
<quoted-fromusr>${parsed.fromWxid ?? ""}</quoted-fromusr>
<quoted-content>${refContent.slice(0, 300).replace(/</g, "&lt;")}</quoted-content>`;
}

export function formatOutbound(text: string, opts?: { trim?: boolean }): string {
  let out = text;
  if (opts?.trim !== false) out = out.trim();
  return out;
}

