import { SeenTracker, buildDedupeKey } from "../webhook-receiver.js";
import { enrichImageMessage, enrichImageMessageFromV1, enrichImageMessageFromV1Cdn, enrichFileMessage, enrichFileMessageFromV1Binary, enrichVideoMessage, enrichVideoMessageFromV1, isV1SchemaVideo, enrichVoiceMessage, enrichVoiceMessageFromV1, isV1SchemaVoice, enrichFileMessageViaMcp, isV1SchemaImage, isV1SchemaFile, type ImageEnrichResult, type MediaEnrichResult } from "./media-enrich.js";
import { getDefaultAccountRegistry } from "../account-state.js";
import type { WppInboundMessage, WppWebhookPayload } from "../types.js";
import type { WppAccountCtx } from "../send/factory.js";

// 问题: 群聊发文件/图 (enrich 慢, 下载大文件几秒) + @机器人, 触发消息 dispatch 时文件还没入库。
// 解法: enrich 时 trackEnrich 记录 promise, 触发 dispatch 前 waitForPendingEnrich 等待同 sender 的 enrich 完成。
const pendingEnrichs = new Map<string, Promise<void>>();

// v1.3.54 RELAY-TRIGGER 节流: 同群同接龙标题, RELAY_THROTTLE_MS 内只触发一次 AI 鼓励。
// 背景: vendor 每次有人接龙都推送完整接龙 (type=49 app), 若不节流 AI 每条都回 → 刷屏。
// key = `${peerId}:${content 首行前 30 字}` (同一接龙 title 指纹); 被 @ 的消息 content 不同 → 不受节流影响。
const RELAY_THROTTLE_MS = 5 * 60 * 1000;
const relayTriggerAt = new Map<string, number>();
/** 测试注入: 重置接龙节流状态 (防测试间污染) */
export function __resetRelayThrottle(): void {
  relayTriggerAt.clear();
}

/** 追踪一次 enrich (key = accountId:sender, 同 sender 串行) */
function trackEnrich<T>(key: string, fn: () => Promise<T>): Promise<T> {
  const p = fn().finally(() => pendingEnrichs.delete(key));
  // 存 Promise<void> 变体 (只等完成), waitForPendingEnrich 用
  pendingEnrichs.set(key, p.then(() => undefined));
  return p;
}

/**
 * 等待同 sender 的 pending enrich 完成 (触发 dispatch 前调, 防 AI 看不到刚发的文件/图)。
 * 超时降级: 极端大文件下载超时 → 不阻塞触发 (AI 少看到该文件, 可接受)。
 */
export async function waitForPendingEnrich(
  accountId: string,
  sender: string,
  timeoutMs = 10_000,
): Promise<void> {
  const p = pendingEnrichs.get(`${accountId}:${sender}`);
  if (!p) return;
  try {
    await Promise.race([p, new Promise<void>((r) => setTimeout(r, timeoutMs))]);
  } catch {
    /* enrich 失败不阻塞 */
  }
}

/** 测试用: 清空 pending enrich (隔离) */
export function clearPendingEnrichs(): void {
  pendingEnrichs.clear();
}

/**
 * 测试用: 模拟一个 pending enrich (用于 waitForPendingEnrich 真测)
 * 镜像私有 trackEnrich: 注册一个 promise, 完成后清理
 * v1.3.18: 加此 helper 让 tests/pending-enrich.test.ts 能真测 "有 pending 时等待完成"
 */
export function __testSetPendingEnrich(key: string, fn: () => Promise<unknown>): void {
  const p = fn().finally(() => pendingEnrichs.delete(key));
  pendingEnrichs.set(key, p.then(() => undefined));
}

export interface WppInboundHandlerOpts {
  accountId: string;
  triggerConfig: WppTriggerConfig;
  triggerCtx: WppAccountTriggerCtx;
  /** 是否真发 (false = debug 模式, enrich 但不 dispatch) */
  enableDispatch?: boolean;
  /** 外部 dispatcher hook (接入 OpenClaw runtime) — 暂记日志 */
  onDispatch?: (msg: WppInboundMessage, batch: WppInboundMessage[]) => void | Promise<void>;
  /** v1.2.3 PAIRING: 账号是否启用 DM 配对 (accounts/<id>.json 显式 dmPairingEnabled: true) — 热切走 triggerCtx, 此为创建时快照兜底 */
  dmPairingEnabled?: boolean;
  /** v1.2.4 GROUP-CONTEXT: 是否缓冲非触发群消息进上下文 (默认 false, 显式 true 才开启) — 热切走 triggerCtx */
  groupContextEnabled?: boolean;
  /** v1.2.3 PAIRING: 配对拦截回调 — 由 index.ts wire. handler 只识别/解析/调用, 不做 fs/发送副作用 */
  onPairingAttempt?: (ctx: { msg: WppInboundMessage; code: string }) => void | Promise<void>;
  /** v1.3.39 FILEHELPER: filehelper 命令回调 (只处理命令, 非命令仍过滤) — 由 index.ts wire */
  onFileHelperCommand?: (ctx: { msg: WppInboundMessage; command: string }) => void | Promise<void>;
  /** 是否把 chat-history (type=53) 解析成接龙 items 注入 prompt */
  parseRelay?: boolean;
  /** vendor ctx (baseUrl/tokenKey/authcode) — 媒体下载/OSS 上传用 */
  vendorCtx?: WppAccountCtx;
  /** DM allowFrom 白名单 (caller 加载, handler 透传给 trigger) */
  allowFrom?: string[];
  /** v1.2.0 VENDOR-MCP: 是否启用 MCP 文件增强 (默认 true; false 则纯确定性回复兜底) */
  mcpEnabled?: boolean;
}

/**
 * 创建主 inbound handler — 给 webhook/WS 推送使用.
 * - parse + 4-way triggers + enrichAndSave + (optional) dispatch
 */
export function createWppInboundHandler(
  opts: WppInboundHandlerOpts,
): { handle: (payload: WppWebhookPayload) => Promise<void>; flushAll: () => Promise<void> } {
  const debouncer = new WppInboundDebouncer({
    onFlush: async (batch) => {
      // 先 enrich (DB 也带 OSS URL) 再 save; enrich 失败不阻塞 (非致命)
      for (const m of batch) {
        // 图片: v0 schema (content 含 <img> XML) 走 CdnDownloadImage 完整大图; v1 schema (无 XML) 走 DownloadImg 64KB
        if (m.msgType === 3 && opts.vendorCtx) {
          const v0Path = m.content.includes("<img");
          if (v0Path) {
            try {
              const imgR = await enrichImageMessage(opts.vendorCtx, m.content);
              if (imgR.mediaUrl) {
                m.content = `${m.content}\n[图片] ${imgR.mediaUrl}`;
                log.info(`[WPP v1.3.74] image enrich ok: msgId=${m.msgId} url=${imgR.mediaUrl}`);
              }
            } catch (e) {
              log.warn(`[WPP v1.3.74] image enrich failed (non-fatal): ${formatErr(e)}`, { msgId: m.msgId });
            }
          } else {
            // v1 schema 图片: v1.2.5 新版推送带 cdn_download_contexts → CdnDownloadImage 完整大图 (优先)
            //   失败 → DownloadImg 64KB 兜底 (旧路径)
            const v1Info = isV1SchemaImage(m.raw);
            if (v1Info.isV1 && v1Info.localId && v1Info.toWxid) {
              let imgR: ImageEnrichResult | null = null;
              // 路径 1 (v1.2.5 首选): cdn_download_contexts → CdnDownloadImage 完整大图
              if (v1Info.cdnDownloadCtx) {
                try {
                  imgR = await trackEnrich(`${m.accountId}:${m.fromWxid}`, () =>
                    enrichImageMessageFromV1Cdn(opts.vendorCtx!, v1Info.cdnDownloadCtx!, v1Info.md5),
                  );
                  if (imgR.mediaUrl) {
                    m.content = `${m.content}\n[图片] ${imgR.mediaUrl}`;
                    log.info(`[WPP v1.2.5 IMAGE-CDN-DOWNLOAD] image enrich ok: msgId=${m.msgId} url=${imgR.mediaUrl} size=${imgR.mediaSize}`);
                  } else {
                    log.info(`[WPP v1.2.5 IMAGE-CDN-DOWNLOAD] miss (fallback DownloadImg): msgId=${m.msgId} err=${imgR.error}`);
                    imgR = null;
                  }
                } catch (e) {
                  log.warn(`[WPP v1.2.5 IMAGE-CDN-DOWNLOAD] exception (fallback): ${formatErr(e)}`, { msgId: m.msgId });
                  imgR = null;
                }
              }
              // 路径 2 (旧): DownloadImg 64KB 兜底
              if (!imgR) {
                try {
                  imgR = await enrichImageMessageFromV1(
                    opts.vendorCtx,
                    v1Info.localId,
                    v1Info.toWxid,
                    v1Info.md5,
                    v1Info.dataLen, // v1.3.70: 新 vendor DownloadImg 必填 data_len
                  );
                  if (imgR.mediaUrl) {
                    m.content = `${m.content}\n[图片] ${imgR.mediaUrl} (注: vendor v1 schema 推送, 仅下载首 64KB, 大图部分可能截断)`;
                    log.info(`[WPP v1.2.0 V1-SCHEMA-ENRICH] image enrich ok: msgId=${m.msgId} localId=${v1Info.localId} url=${imgR.mediaUrl} size=${imgR.mediaSize}`);
                  } else {
                    log.warn(`[WPP v1.3.74] v1 schema image enrich returned no url: msgId=${m.msgId} localId=${v1Info.localId} error=${imgR.error}`, { msgId: m.msgId });
                  }
                } catch (e) {
                  log.warn(`[WPP v1.3.74] v1 schema image enrich failed (non-fatal): ${formatErr(e)}`, { msgId: m.msgId });
                }
              }
            }
          }
        }

        // 视频: msgType=43 → 新版 video.download_context → DownloadVideo (优先); 旧 videomsg XML 兜底
        if (m.msgType === 43 && opts.vendorCtx) {
          let vR: MediaEnrichResult | null = null;
          const v1Video = isV1SchemaVideo(m.raw);
          if (v1Video.isV1 && v1Video.videoCtx) {
            try {
              vR = await trackEnrich(`${m.accountId}:${m.fromWxid}`, () =>
                enrichVideoMessageFromV1(opts.vendorCtx!, v1Video.videoCtx!),
              );
              if (!vR.mediaUrl) {
                log.info(`[WPP v1.3.8 VIDEO-DOWNLOAD] miss (fallback XML): msgId=${m.msgId} err=${vR.error}`);
                vR = null;
              }
            } catch (e) {
              log.warn(`[WPP v1.3.8 VIDEO-DOWNLOAD] exception (fallback): ${formatErr(e)}`, { msgId: m.msgId });
              vR = null;
            }
          }
          // 旧路径: <videomsg> XML
          if (!vR && (m.content.includes("<videomsg") || m.content.includes("videomsg"))) {
            try {
              vR = await enrichVideoMessage(opts.vendorCtx, m.content);
            } catch (e) {
              log.warn(`[WPP v1.3.74] video enrich exception: ${formatErr(e)}`, { msgId: m.msgId });
              vR = null;
            }
          }
          if (vR?.mediaUrl) {
            m.content = `${m.content}\n[视频] ${vR.mediaUrl}`;
            log.info(`[WPP v1.3.8] video enrich ok: msgId=${m.msgId} url=${vR.mediaUrl}`);
          } else if (vR?.error) {
            log.warn(`[WPP v1.3.8] video enrich failed (non-fatal): err=${vR.error}`, { msgId: m.msgId });
          }
        }

        // 名片: msgType=42 (contact_card) → 从 push_content 提取名片名 (如 "[名片]龙脉") 注入 content, AI 知道是谁的名片
        if (m.msgType === 42) {
          const pushContent = (m.raw as Record<string, unknown> | null)?.push_content as string | undefined;
          const cardMatch = pushContent?.match(/\[名片\]\s*([^\s:：]+)/);
          const cardName = cardMatch?.[1]?.trim();
          if (cardName) {
            m.content = `${m.content}\n[名片] ${cardName}`;
            log.info(`[WPP v1.3.12 CARD] contact card: msgId=${m.msgId} name=${cardName}`);
          } else {
            log.info(`[WPP v1.3.12 CARD] contact card (无名称): msgId=${m.msgId}`);
          }
        }

        // 语音: msgType=34 → 下载 + OSS + SiliconFlow STT 转写文字注入 content (AI 看到文本)
        if (m.msgType === 34 && opts.vendorCtx) {
          let vR: MediaEnrichResult | null = null;
          // 路径 1 (v1.2.6 首选): 新版 voice.download_context → DownloadVoiceBinary
          const v1Voice = isV1SchemaVoice(m.raw);
          if (v1Voice.isV1 && v1Voice.voiceCtx) {
            try {
              // v1.3.22 VENDOR-TRANSCRIPT: 透传 vendor 自带转写 (voice.transcript), 免插件 STT
              const rawVoice = (m.raw as Record<string, unknown> | undefined)?.voice as
                | Record<string, unknown>
                | undefined;
              const vendorTranscript =
                typeof rawVoice?.transcript === "string" && rawVoice.transcript.length > 0
                  ? (rawVoice.transcript as string)
                  : undefined;
              vR = await trackEnrich(`${m.accountId}:${m.fromWxid}`, () =>
                enrichVoiceMessageFromV1(opts.vendorCtx!, v1Voice.voiceCtx!, vendorTranscript),
              );
              if (!vR.mediaUrl) {
                log.info(`[WPP v1.2.6 VOICE-DOWNLOAD-BINARY] miss (fallback): msgId=${m.msgId} err=${vR.error}`);
                vR = null;
              }
            } catch (e) {
              log.warn(`[WPP v1.2.6 VOICE-DOWNLOAD-BINARY] exception (fallback): ${formatErr(e)}`, { msgId: m.msgId });
              vR = null;
            }
          }
          // 路径 2 (旧): <voicemsg> XML → DownloadVoice
          if (!vR && m.content.includes("<voicemsg")) {
            try {
              vR = await enrichVoiceMessage(opts.vendorCtx, m.content);
            } catch (e) {
              log.warn(`[WPP v1.3.74] voice enrich exception: ${formatErr(e)}`, { msgId: m.msgId });
              vR = null;
            }
          }
          // 处理结果
          if (vR?.mediaUrl) {
            const sttText = vR.filename ?? "";
            const sttSuffix = sttText ? `\n[转写] ${sttText}` : "";
            m.content = `${m.content}\n[语音] ${vR.mediaUrl}${sttSuffix}`;
            log.info(`[WPP v1.2.6] voice enrich ok: msgId=${m.msgId} url=${vR.mediaUrl} stt=${sttText ? "yes" : "no"}`);
          } else if (vR?.error) {
            log.warn(`[WPP v1.2.6] voice enrich failed (non-fatal): err=${vR.error}`, { msgId: m.msgId });
          }
        }

        // 文件: v0 schema (msgType 6 或 appmsg 含 <type>6/8</type>) 走 enrichFileMessage 完整下载;
        //       v1 schema 无下载参数 (见下方 fallback)
        const isV0FileContent =
          m.content.includes("<appmsg") &&
          (m.content.includes("<type>6</type>") || m.content.includes("<type>8</type>"));
        if (opts.vendorCtx && (m.msgType === 6 || (m.msgType === 49 && isV0FileContent))) {
          try {
            const fR = await enrichFileMessage(opts.vendorCtx, m.content);
            if (fR.mediaUrl) {
              m.content = `${m.content}\n[文件] ${fR.filename} (${fR.size ?? "?"} bytes) ${fR.mediaUrl}`;
              log.info(`[WPP v1.3.74] file enrich ok: msgId=${m.msgId} name=${fR.filename} url=${fR.mediaUrl} (msgType=${m.msgType})`);
            } else {
              m.content = `${m.content}\n[文件] ${fR.filename} (${fR.size ?? "?"} bytes, 下载失败: ${fR.error ?? "unknown"})`;
              log.warn(`[WPP v1.3.74] file enrich failed (non-fatal): name=${fR.filename} err=${fR.error}`, {
                msgId: m.msgId,
              });
            }
          } catch (e) {
            log.warn(`[WPP v1.3.74] file enrich exception: ${formatErr(e)}`, { msgId: m.msgId });
          }
        } else if (m.msgType === 49) {
          // v1 schema 文件 (kind=app, app.category=file)
          //   失败 → v1.2.0 MCP 兜底 → 最后确定性回复 (禁 AI 猜路径读文件)
          const v1File = isV1SchemaFile(m.raw);
          if (v1File.isV1) {
            const filename = v1File.filename ?? "(未知文件名)";
            const ext = v1File.ext ?? "";
            const localId = (m.raw as { local_id?: number })?.local_id;
            let gotUrl = false;

            // 路径 1 (v1.2.5 首选): DownloadFileBinary 完整下载 (新版推送自带 download_context)
            if (opts.vendorCtx && v1File.downloadCtx) {
              try {
                const fR = await trackEnrich(`${m.accountId}:${m.fromWxid}`, () =>
                  enrichFileMessageFromV1Binary(opts.vendorCtx!, v1File.downloadCtx!, filename, ext),
                );
                if (fR.mediaUrl) {
                  m.content = `${m.content}\n[文件] ${filename} (${ext ? ext.toUpperCase() : "未知格式"}, ${fR.size ?? "?"} bytes) ${fR.mediaUrl}`;
                  log.info(`[WPP v1.2.5 FILE-DOWNLOAD-BINARY] ok: msgId=${m.msgId} name=${filename} url=${fR.mediaUrl}`);
                  gotUrl = true;
                } else {
                  log.info(`[WPP v1.2.5 FILE-DOWNLOAD-BINARY] miss (fallback to MCP): msgId=${m.msgId} name=${filename} err=${fR.error}`);
                }
              } catch (e) {
                log.warn(`[WPP v1.2.5 FILE-DOWNLOAD-BINARY] exception (fallback): ${formatErr(e)}`, { msgId: m.msgId });
              }
            }

            // 路径 2: MCP 增强 (旧路径, 只调只读工具, 不碰写)
            if (!gotUrl && opts.vendorCtx && localId && opts.mcpEnabled !== false) {
              try {
                const fR = await enrichFileMessageViaMcp(localId, filename, m.accountId);
                if (fR.mediaUrl) {
                  m.content = `${m.content}\n[文件] ${filename} (${ext ? ext.toUpperCase() : "未知格式"}) ${fR.mediaUrl}`;
                  log.info(`[WPP v1.2.0 VENDOR-MCP] file via MCP ok: msgId=${m.msgId} localId=${localId} url=${fR.mediaUrl}`);
                  gotUrl = true;
                } else {
                  log.info(`[WPP v1.2.0 VENDOR-MCP] file via MCP miss (fallback): msgId=${m.msgId} localId=${localId} err=${fR.error}`);
                }
              } catch (e) {
                log.warn(`[WPP v1.2.0 VENDOR-MCP] file via MCP exception: ${formatErr(e)}`, { msgId: m.msgId });
              }
            }

            // 兜底: 都失败 → 确定性回复 (禁 AI 猜路径)
            if (!gotUrl) {
              m.content = `${m.content}\n[系统提示-文件限制] 此文件消息仅有文件名元数据, vendor 当前不提供文件内容下载 (MCP 增强未命中), 你无法读取文件内容。\n禁止: 用 find/ls 搜索 *.pdf 或任何文件、猜测/拼接文件路径、读取系统里任何现有文件 (可能是旧文件误导)。\n只需: 基于文件名回复用户 (例如"收到文件 ${filename}, 但当前平台无法读取文件内容, 需要内容请换图片或文本发送"), 或询问用户是否改用文本/图片发送。`;
              log.info(`[WPP v1.2.0 NO-PATH-GUESS] file msg (v1 schema) fallback: msgId=${m.msgId} name=${filename} ext=${ext}`);
            }
          }
        }

        // 捕获引用消息 svrid → 存映射表 (供未来引用定位)
        if (m.content.includes("<refermsg")) {
          try {
            await captureQuoteSvrid(m.content, m.accountId);
          } catch (e) {
            warn(`quote svrid capture err (non-fatal): ${formatErr(e)}`);
          }
        }

        // 引用消息: 查 DB 被引用消息, 把原媒体 OSS URL 注入 content → AI 看到原图/原资源
        if (m.msgType === 49) {
          let quotedMsgId = "";
          try {
            const appRef = extractReferencedFromApp(m.raw);
            if (appRef) {
              quotedMsgId = appRef.newMsgId ?? appRef.svrId ?? "";
            } else if (m.content.includes("<refermsg")) {
              const parsed = parseQuoteXml(m.content);
              quotedMsgId = parsed?.msgId ?? "";
            } else {
              // 旧 reply_context (msg_id 常对不上, 保留兜底)
              const rc = extractReferencedFromReplyContext(m.raw);
              if (rc?.svrId || rc?.newMsgId) {
                quotedMsgId = rc.svrId ?? rc.newMsgId ?? "";
              }
            }
            if (quotedMsgId) {
              // v1.3.57 P2-4 (2026-08-13 交付审阅): 引用解析查全方向 — bot 回复也入库 (outbound),
              //   用户引用 bot 的图/文件时默认 direction=inbound 查不到, 加 any (与 dispatcher.ts:216 对齐)
              const quoted = await getMessageByMsgIdOrNewId(quotedMsgId, undefined, m.accountId, { direction: "any" })
                ?? (await getMessageById(quotedMsgId, m.accountId));
              if (quoted?.content) {
                // 匹配 enrich 注入的 [图片]/[视频]/[语音]/[文件] URL, 取第一个注入
                const mediaMatch = quoted.content.match(/\[(图片|视频|语音|文件)\]\s+(?:[^\n]*?)\s*(https?:\/\/\S+)/);
                if (mediaMatch) {
                  const tag = mediaMatch[1] ?? "媒体";
                  const ossUrl = mediaMatch[2] ?? "";
                  info(`[WPP v1.3.74] QUOTE media inject: msgId=${m.msgId} quoted.msgId=${quotedMsgId} type=${tag} ossUrl=${ossUrl}`);
                  m.content = `${m.content}\n[引用${tag}] ${ossUrl}`;
                }
              }
            }
          } catch (e) {
            warn(`quote media inject err (non-fatal): ${formatErr(e)}`);
          }
        }
      }

      // Step 2: persist (DB 落 enrich 后的 content) — v1.2.4 老板拍板 "只入白名单":
      //   黑名单群/非 allowlist 群/DM 白名单外/自回环 (shouldTrigger via=blocked) 不入库 (隐私)
      //   白名单内消息 (含触发 + 白名单群非触发) 入库 → DB 按人查历史依赖
      const ctxForTriggerEarly = { ...opts.triggerCtx, allowFrom: opts.triggerCtx.allowFrom };
      const persistResults = new Map<WppInboundMessage, ReturnType<typeof shouldTrigger>>();
      for (const m of batch) {
        const t = shouldTrigger(m, opts.triggerConfig, ctxForTriggerEarly);
        persistResults.set(m, t);
      }
      const persistBatch = batch.filter((m) => persistResults.get(m)?.via !== "blocked");
      const r = await enrichBatch(persistBatch);
      if (r.failed > 0) {
        warn(`inbound batch persist: ${r.failed}/${persistBatch.length} failed (skipped ${batch.length - persistBatch.length} blocked)`);
      }

      // Step 3: relay 解析 (接龙): 给 prompt 注入 items
      // v1.3.54 RELAY-TRIGGER: 用 isRelayMessage 识别 (真实 vendor 接龙 type=49 app, 非 53)
      for (const m of batch) {
        if (opts.parseRelay !== false && isRelayMessage(m)) {
          try {
            const relay = parseRelayText(m.content);
            info(`relay detected: title="${relay.title.slice(0, 30)}", items=${relay.items.length} msgType=${m.msgType}`);
            m.content = `[接龙] ${relay.title}\n` +
              relay.items.map((it) => `${it.index}. ${it.text ?? ""}`).join("\n");
          } catch (e) {
            warn(`relay parse failed: ${formatErr(e)}`);
          }
        }
        // 注入 at 列表 (供 prompt / ctx 字段用)
        if (m.peerKind === "group") {
          const atList = extractAtUserList(m.content);
          if (atList.length > 0) {
            // 嵌入 raw 的 atUserList 字段 — Phase D 简易版, Phase F 正式注入 ctx
            (m.raw as Record<string, unknown>).atUserList = atList;
          }
        }

        // 红包消息: 处理后 continue, 不触发 AI 回复
        if (isRedPacketMessage(m)) {
          processRedPacket(m);  // log + 提取 url/key, 未来可接 auto-open
          continue;
        }
      }

      const triggerResults = persistResults; // Step 2 已算 (same ctxForTrigger + shouldTrigger)
      const dispatched: WppInboundMessage[] = [];
      for (const [m, t] of triggerResults) {
        // v1.3.72 红包消息不触发 AI (老板 2026-08-20): 收到红包静默入库, 不瞎回复 (415 行的 continue 只跳过 relay 循环, 这里必须再拦一次)
        if (isRedPacketMessage(m)) continue;
        // v1.3.72 系统通知 (msg_type=10000, 含红包领取/转账/安全提醒) 不触发 AI (老板 2026-08-20): 系统消息无需 AI 回复
        if (m.msgType === 10000) continue;
        // v1.3.39 FILEHELPER: filehelper 命令不 dispatch (只走命令回调, 不进 AI)
        if (m.peerId === "filehelper" && /^\s*\//.test(m.content)) continue;
        // v1.3.54 RELAY-TRIGGER (老板 8-12 拍板): 接龙消息强制触发 AI (即使没人 @)
        //   老板诉求"对华为群接龙进行鼓励" — 群内接龙活动要让 AI 介入给鼓励, 不能静默
        //   节流: 同群同接龙 5 分钟内只触发一次 (vendor 每次有人接龙都推完整接龙, 全回会刷屏)
        //   v1.3.57 P0-2 + P2-1 (2026-08-13 交付审阅): 强制触发前检查 via!=="blocked" (防黑名单群/
        //   自回环绕过); 节流 key 并入 accountId (防多账号同群互相节流)
        if (opts.enableDispatch !== false && isRelayMessage(m)) {
          const t = triggerResults.get(m);
          if (t?.via === "blocked") continue; // P0-2: 黑名单群/自回环/非白名单 → 不强制触发
          const titleKey = (m.content ?? "").split("\n")[0]?.slice(0, 30) ?? "";
          const throttleKey = `${m.accountId}:${m.peerId}:${titleKey}`; // P2-1: 并入 accountId
          const now = Date.now();
          // v1.3.63 P2: relayTriggerAt 写时清理过期 key (防无界增长; 照 SeenTracker 范式)
          if (relayTriggerAt.size > 1000) {
            for (const [k, ts] of relayTriggerAt) {
              if (now - ts > RELAY_THROTTLE_MS) relayTriggerAt.delete(k);
            }
          }
          const lastAt = relayTriggerAt.get(throttleKey) ?? 0;
          if (now - lastAt >= RELAY_THROTTLE_MS) {
            relayTriggerAt.set(throttleKey, now);
            m.trigger = "msgType";
            dispatched.push(m);
            info(`relay force-trigger dispatch: peer=${m.peerId} msgId=${m.msgId} via=msgType (throttle key=${throttleKey.slice(0, 40)})`);
          } else {
            debug(`relay throttled (last ${Math.round((now - lastAt) / 1000)}s ago, TTL ${RELAY_THROTTLE_MS / 1000}s): ${throttleKey.slice(0, 40)}`);
          }
          continue;
        }
        if (t.triggered && t.via !== "blocked") {
          m.trigger = t.via ?? "at";
          if (t.via === "at" || t.via === "keyword" || t.via === "msgType" ||
              t.via === "quoteBot" || t.via === "group-open") {
            dispatched.push(m);
          }
        }
      }

      if (opts.enableDispatch !== false && opts.onPairingAttempt &&
          (opts.dmPairingEnabled || opts.triggerCtx.dmPairingEnabled)) {
        for (const m of batch) {
          if (m.peerKind !== "direct") continue; // 只拦私聊 (群聊配对无意义)
          const t = triggerResults.get(m);
          if (t?.via !== "blocked") continue; // 已在白名单 → 正常触发, 不拦
          if (opts.triggerCtx.botWxid && m.fromWxid === opts.triggerCtx.botWxid) continue; // 自回环 guard
          const code = extractPairCode(m.content);
          if (code) {
            try {
              await opts.onPairingAttempt({ msg: m, code });
              log.info(`[WPP v1.2.3 PAIRING] attempt handled: account=${opts.accountId} from=${m.fromWxid}`);
            } catch (e) {
              log.warn(`[WPP v1.2.3] pairing attempt failed (non-fatal): ${formatErr(e)}`, { accountId: opts.accountId, fromWxid: m.fromWxid });
            }
          }
        }
      }

      // v1.3.39 FILEHELPER: 只处理命令, 非命令不处理 (老板 2026-08-11)
      //   识别 filehelper 会话 (peer_id=filehelper) 的命令 → 回调, 不进 AI dispatch
      if (opts.enableDispatch !== false && opts.onFileHelperCommand) {
        for (const m of batch) {
          if (m.peerId !== "filehelper") continue;
          const cmd = m.content.trim();
          if (!/^\//.test(cmd)) continue; // 非命令跳过 (仍不处理)
          try {
            await opts.onFileHelperCommand({ msg: m, command: cmd });
            log.info(`[WPP v1.3.39 FILEHELPER] command handled: ${cmd.split(/\s+/)[0]}`);
          } catch (e) {
            log.warn(`[WPP v1.3.39 FILEHELPER] command failed: ${formatErr(e)}`);
          }
        }
      }

      // 无可触发 → 早退 (防空转)
      if (dispatched.length === 0) return;

      info(`inbound dispatch: ${dispatched.length}/${batch.length} triggered (vias: ${dispatched.map((d) => d.trigger).join(",")})`);

      if (opts.enableDispatch !== false && opts.onDispatch) {
        for (const m of dispatched) {
          await opts.onDispatch(m, batch);
        }
      }
    },
    onError: (err, batch) => {
      warn(`inbound batch error: ${formatErr(err)}`, { size: batch.length });
    },
  });

  // SeenTracker 去重: 同一条消息从 webhook/business-callback/WS 3 条路径进入时只处理一次
  const seenTracker = new SeenTracker();

  return {
    handle: async (payload: WppWebhookPayload): Promise<void> => {
      // business callback 可能是 AddMsgs[] 多条, 逐条 parse
      const msgs = payloadToAllInboundMessages(opts.accountId, payload);

      // 私聊 peerId 修正: bot 自己发的私聊 (fromWxid===selfWxid) → 对方是 toWxid, 否则是自己 (sessionKey 串位)
      try {
        const acct = getDefaultAccountRegistry().get(opts.accountId);
        const selfWxid = acct?.selfWxid;
        if (selfWxid) {
          for (const m of msgs) {
            if (m.peerKind === "direct") {
              if (m.fromWxid === selfWxid && m.toWxid) {
                // 老板自己发的私聊 → 对方是 toWxid
                m.peerId = m.toWxid;
              }
              // 别人发的私聊: peerId 已经是 fromWxid (对方), 无需改
            }
          }
        }
      } catch (e) {
        warn(`peerId fixup skipped (non-fatal): ${formatErr(e)}`);
      }

      if (msgs.length === 0) {
        // payload 解析失败: warn 打印摘要供排查 (v1.3.63 P3: 去掉 payload 内容, 只记 keys + 计数 — 内容可能含聊天文本)
        const payloadData = (payload as Record<string, unknown>)?.Data as Record<string, unknown> | undefined;
        const payloadMsgs = payloadData?.messages;
        const msgCount = Array.isArray(payloadMsgs) ? (payloadMsgs as unknown[]).length : undefined;
        warn(`inbound parse dropped: account=${opts.accountId} payloadKeys=${Object.keys((payload ?? {}) as object).join(",")} dataKeys=${Object.keys(payloadData ?? {}).join(",")} messagesLen=${msgCount ?? "n/a"}`);
        return;
      }
      for (const m of msgs) {
        // 双重去重: SeenTracker 内存态 + DB 持久化 (vendor 重放消息 / gateway 重启后防重复 dispatch)
        const dk = buildDedupeKey(undefined, m.newMsgId, m.msgId, m.content);
        if (!seenTracker.check(dk)) {
          continue;
        }
        // DB 兜底: 内存去重通过但 DB 已有同消息 (重启后 SeenTracker 重置场景)
        if (m.msgId || m.newMsgId) {
          try {
            const existing = await getMessageByMsgIdOrNewId(m.msgId, m.newMsgId, m.accountId);
            if (existing) {
              log.debug(`inbound dedup (db): skip msgId=${m.msgId} newMsgId=${m.newMsgId} (already persisted)`);
              continue;
            }
          } catch (e) {
            log.warn(`inbound dedup (db) check failed: ${formatErr(e)}`, { msgId: m.msgId });
          }
        }
        debouncer.enqueue(m);
      }
    },
    flushAll: async (): Promise<void> => {
      await debouncer.flushAll();
    },
  };
}

/** Re-export for compat */
export type WppInboundCallbacks = DebouncerCallbacks;

// src/inbound/debouncer.ts - 1.5s timer-based batch flush
// 关键: VOICE/系统消息 bypass; key = accountId:peerKind:peerId:fromWxid; .unref() 防保活

import { info, warn, formatErr } from "../core/logger.js";
import { DEFAULT_DEBOUNCE_MS } from "../core/constants.js";
import type { WppInboundMessage } from "../types.js";

export interface DebouncerCallbacks {
  /** Flush 时被回调 (1 批 N 条) */
  onFlush: (batch: WppInboundMessage[]) => void | Promise<void>;
  /** Flush 失败 (handler 内部错误) */
  onError?: (err: unknown, batch: WppInboundMessage[]) => void;
  /** 是否 control command (绕过 debouncer) */
  isControlCommand?: (msg: WppInboundMessage) => boolean;
}

export interface DebouncerOpts extends DebouncerCallbacks {
  /** 默认 1.5s (标准值) */
  intervalMs?: number;
}

/**
 * Per-key inbox. Same sender-target within intervalMs gets merged; on flush, batch emitted.
 * 触发顺序: 入队 → 如果已有 timer 则 reset → 设新 timer;
 *           timer fires → 取 batch → reset key;
 *           VOICE / SYSTEM / control → 直接 flush
 */
export class WppInboundDebouncer {
  private readonly intervalMs: number;
  private readonly timers = new Map<string, NodeJS.Timeout>();
  private readonly buffers = new Map<string, WppInboundMessage[]>();
  private readonly onFlush: DebouncerCallbacks["onFlush"];
  private readonly onError?: DebouncerCallbacks["onError"];
  private readonly isControlCommand?: DebouncerCallbacks["isControlCommand"];

  constructor(opts: DebouncerOpts) {
    this.intervalMs = opts.intervalMs ?? DEFAULT_DEBOUNCE_MS;
    this.onFlush = opts.onFlush;
    this.onError = opts.onError;
    this.isControlCommand = opts.isControlCommand;
  }

  private key(msg: WppInboundMessage): string {
    return `${msg.accountId}:${msg.peerKind}:${msg.peerId}:${msg.fromWxid}`;
  }

  /** 入队 (分组到 batch, 起 timer) */
  enqueue(msg: WppInboundMessage): void {
    // 系统消息 / VOICE / control 直接 flush
    if (
      msg.msgType === 10000 ||
      msg.msgType === 34 /* VOICE (silk) */ ||
      msg.msgType === 10002 ||
      (this.isControlCommand && this.isControlCommand(msg))
    ) {
      void this.flushBatch([msg]);
      return;
    }

    const k = this.key(msg);
    const list = this.buffers.get(k) ?? [];
    list.push(msg);
    this.buffers.set(k, list);

    const existing = this.timers.get(k);
    if (existing) clearTimeout(existing);

    const timer = setTimeout(() => {
      void this.flushKey(k);
    }, this.intervalMs);
    // 不保活
    timer.unref?.();
    this.timers.set(k, timer);
  }

  private async flushKey(k: string): Promise<void> {
    const batch = this.buffers.get(k) ?? [];
    this.buffers.delete(k);
    const t = this.timers.get(k);
    if (t) {
      clearTimeout(t);
      this.timers.delete(k);
    }
    if (batch.length === 0) return;
    await this.flushBatch(batch);
  }

  private async flushBatch(batch: WppInboundMessage[]): Promise<void> {
    try {
      await this.onFlush(batch);
    } catch (e) {
      warn(`debouncer flush batch failed: ${formatErr(e)}`, { size: batch.length });
      if (this.onError) this.onError(e, batch);
    }
  }

  /** 强制 flush (例如 shutdown) */
  async flushAll(): Promise<void> {
    const keys = Array.from(this.buffers.keys());
    for (const k of keys) {
      await this.flushKey(k);
    }
    info(`debouncer flushAll: ${keys.length} keys`);
  }

  /** 清掉全部 pending (测试用) */
  clear(): void {
    for (const t of this.timers.values()) clearTimeout(t);
    this.timers.clear();
    this.buffers.clear();
  }

  /** 当前 buffered 条数 (测试 + 监控) */
  size(): number {
    let n = 0;
    for (const list of this.buffers.values()) n += list.length;
    return n;
  }
}

// src/inbound/triggers.ts - 4-way OR 触发器判定
// 范式: `@mention` | `keyword` | `msgType` | `quoteBot` 任一命中即触发; 带 DM/群白名单门禁

import type { WppInboundMessage } from "../types.js";
import { isBotMentionedByText } from "./parser/mention.js";

export type GroupPolicyValue = "open" | "disabled" | "allowlist" | "closed";

export interface WppTriggerConfig {
  /** 群聊 requireAtMention — 注意: 当前未在 shouldTrigger 内实现 (见下方说明) */
  requireAtMention: boolean;
  keywordTrigger: {
    enabled: boolean;
    keywords: string[];
    mode?: "exact" | "contains" | "regex";
  };
  msgTypeTrigger: {
    enabled: boolean;
    appMsgTypes?: number[]; // vendor app msg 类型白名单 (e.g. 接龙 53)
    /** 群消息触发白名单 — 缺省全群触发; 配后只触发列出的群 */
    whitelistGroups?: string[];
  };
  quoteBotTrigger: {
    enabled: boolean;
  };
  /** 全局黑名单 (群 wxid 列表) */
  blacklistGroups: string[];
  /** 是否启用 debug 短路 (强制触发, 不真发) */
  chatroomDebug?: boolean;
  /**
   * 群聊策略 (live 路径强制执行)
   * - "open"      全放行 (走 4-way trigger)
   * - "disabled"  全部拒绝
   * - "allowlist" 仅 groupAllowFrom 内群可触发
   * - "closed"    全部拒绝
   */
  groupPolicy?: GroupPolicyValue;
  /** groupPolicy=allowlist 时的群白名单 */
  groupAllowFrom?: string[];
}

export interface WppAccountTriggerCtx {
  /** 当前账号 self wxid (用于 @mention 检测 + 自回环过滤) */
  botWxid: string | null;
  /** 当前账号昵称 (用于 @昵称 中文匹配 — vendor 群 @ 用中文昵称) */
  botNickname: string | null;
  /** 历史群 @ 缓存 (key=chatroomId) — 留接口先不实装 */
  lastGroupMentionByChatroom?: Map<string, number>;
  /**
   * DM allowFrom 白名单 (从 accounts/<id>.json 读)
   * 长度 = 0: 拒绝所有 DM (fail-closed, 防 P0 联系人 fan-out 重演)
   * 长度 > 0: strict 白名单, 不在列表内一律 blocked
   */
  allowFrom?: string[];
  /** v1.2.3 PAIRING: 运行时可热切 (配对/热重载即时开关) — handler 读 triggerCtx 而非创建时快照 */
  dmPairingEnabled?: boolean;
  /** v1.2.4 GROUP-CONTEXT: 运行时可热切 (默认 false, 显式 true 才缓冲非触发群消息) */
  groupContextEnabled?: boolean;
  /** v1.2.4 GROUP-CONTEXT: 上下文条数 (默认 20) */
  groupContextWindow?: number;
}

/** 决定 message 是否触发 OpenClaw AI 回复 */
export function shouldTrigger(
  msg: WppInboundMessage,
  cfg: WppTriggerConfig,
  ctx: WppAccountTriggerCtx,
): { triggered: boolean; via: "at" | "keyword" | "msgType" | "quoteBot" | "group-open" | "blocked" | null } {
  // 自回环过滤: bot 自己发的消息不回 (防 vendor 回推 self → 自问自答)
  if (ctx.botWxid && msg.fromWxid === ctx.botWxid) {
    return { triggered: false, via: "blocked" };
  }

  // black/group debug 短路
  if (msg.peerKind === "group" && cfg.blacklistGroups.includes(msg.chatroomId ?? "")) {
    return { triggered: false, via: "blocked" };
  }
  if (msg.peerKind === "group" && cfg.chatroomDebug) {
    return { triggered: true, via: "at" };
  }

  // DM 白名单: allowFrom 必须显式包含 sender 才放行; 空列表 = 拒绝所有 (fail-closed 防 fan-out)
  if (msg.peerKind === "direct") {
    const allow = ctx.allowFrom ?? [];
    if (allow.length === 0 || !allow.includes(msg.fromWxid)) {
      return { triggered: false, via: "blocked" }; // fail-closed: 空白名单 = 拒绝
    }
    return { triggered: true, via: "at" }; // 视同被 @ (私聊 always, 白名单内)
  }

  // groupPolicy 检查 (live 路径强制执行)
  if (msg.peerKind === "group") {
    const policy = cfg.groupPolicy ?? "open";
    if (policy === "disabled" || policy === "closed") {
      return { triggered: false, via: "blocked" };
    }
    if (policy === "allowlist") {
      const allowGroups = cfg.groupAllowFrom ?? [];
      if (allowGroups.length > 0 && !allowGroups.includes(msg.chatroomId ?? "")) {
        return { triggered: false, via: "blocked" };
      }
    }
  }

  // GROUP 走 4-way OR
  const botMentioned = isBotMentionedByText(msg.content, ctx.botWxid) ||
    // 群消息 @ 中文昵称 也触发
    (!!ctx.botNickname && msg.content.includes(`@${ctx.botNickname}`));

  if (botMentioned) {
    return { triggered: true, via: "at" };
  }

  if (cfg.msgTypeTrigger.enabled && cfg.msgTypeTrigger.appMsgTypes?.includes(msg.msgType)) {
    if (
      msg.peerKind === "group" &&
      cfg.msgTypeTrigger.whitelistGroups &&
      cfg.msgTypeTrigger.whitelistGroups.length > 0 &&
      !cfg.msgTypeTrigger.whitelistGroups.includes(msg.chatroomId ?? "")
    ) {
      // 群不在白名单内, 此 msgType 不触发 (但保持 enabled 不影响其他类型)
      // 不直接 return, 继续看后面 keyword/quoteBot
    } else {
      return { triggered: true, via: "msgType" };
    }
  }

  if (cfg.quoteBotTrigger.enabled && isQuoteRefToBot(msg.content, ctx.botWxid)) {
    return { triggered: true, via: "quoteBot" };
  }

  if (cfg.keywordTrigger.enabled && cfg.keywordTrigger.keywords.length > 0) {
    if (matchKeyword(msg.content, cfg.keywordTrigger)) {
      return { triggered: true, via: "keyword" };
    }
  }

  return { triggered: false, via: null };
}

function isQuoteRefToBot(content: string, botWxid: string | null): boolean {
  if (!botWxid) return false;
  // 真实引用结构是 <fromusr> (不是 <fromusername>); 老板引用 bot 消息时匹配
  const m = content.match(/<refermsg\b[^>]*>[\s\S]*?<(?:fromusr|fromusername)>([\s\S]*?)<\/(?:fromusr|fromusername)>/);
  return !!(m && m[1] && m[1].trim() === botWxid);
}

function matchKeyword(content: string, kw: { keywords: string[]; mode?: "exact" | "contains" | "regex" }): boolean {
  const mode = kw.mode ?? "contains";
  for (const k of kw.keywords) {
    if (!k) continue;
    if (mode === "exact" && content.trim() === k) return true;
    if (mode === "contains" && content.includes(k)) return true;
    if (mode === "regex") {
      try {
        const re = new RegExp(k);
        if (re.test(content)) return true;
      } catch {
        /* bad regex, skip */
      }
    }
  }
  return false;
}

/** 默认 trigger config (新账号用) */
export function defaultTriggerConfig(): WppTriggerConfig {
  return {
    requireAtMention: false,
    keywordTrigger: { enabled: false, keywords: [], mode: "contains" },
    msgTypeTrigger: { enabled: false, appMsgTypes: [] },
    quoteBotTrigger: { enabled: false },
    blacklistGroups: [],
    chatroomDebug: false,
    groupPolicy: "open",
    groupAllowFrom: [],
  };
}

// src/inbound/parser/mention.ts - 群消息 @user 提取
// 注意: 所有 regex 走 safeMatchAll (截断 4096 + 灾难 regex 检测, 防 ReDoS — gewe A1 教训)

import { isValidAtUser } from "./wxid.js";
import { safeMatchAll } from "../../core/safe-regex.js";

const AT_MENTION_PATTERNS: RegExp[] = [
  // `wxid_xxx@<nickname>` — 群聊 @ 通知
  /(wxid_[a-zA-Z0-9]+)@[^,\s]*/g,
  // `\@wxid_xxx ` 中文 @ + wxid
  /@(wxid_[a-zA-Z0-9]+)/g,
  // `<at user="wxid_xxx">` XML 风格
  /<at\s+user="(wxid_[a-zA-Z0-9]+)"/g,
  // 群 XML: <atuserlist><item><username>wxid_xxx</username>
  /<atuserlist>[\s\S]*?<username>(wxid_[a-zA-Z0-9]+)<\/username>/g,
  // 微信号格式 (e.g. wxid_demo — selfWxid 是微信号非 wxid_, 之前硬要求 wxid_ 前缀漏判)
  /<atuserlist>[\s\S]*?<username>([a-zA-Z][a-zA-Z0-9_-]{5,})<\/username>/g,
  /@([a-zA-Z][a-zA-Z0-9_-]{5,})[^\s@]*/g,
];

/** Extract list of valid wxids mentioned in a group message (去重, 保序) */
export function extractAtUserList(content: string): string[] {
  const out = new Set<string>();
  for (const pat of AT_MENTION_PATTERNS) {
    const matches = safeMatchAll(pat, content);
    for (const m of matches) {
      const wxid = m[1];
      if (wxid && isValidAtUser(wxid)) out.add(wxid);
    }
  }
  return Array.from(out);
}

/** Strip `@bot` text tokens from content (留 emoji 之类) */
export function stripAtMentions(content: string, botWxid: string | null): string {
  if (!botWxid) return content;
  // 匹配 wxid_botwxid 或者 @botwxid 等
  const escaped = botWxid.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const truncated =
    content.length > 4096 ? content.slice(0, 4096) : content; // v1.1.33: 截断防 ReDoS
  return truncated
    .replace(new RegExp(`@${escaped}\\s*`, "g"), "")
    .replace(new RegExp(`\\b${escaped}\\b\\s*`, "g"), "")
    .trim();
}

/** True if message text contains @bot */
export function isBotMentionedByText(content: string, botWxid: string | null): boolean {
  if (!botWxid) return false;
  if (!content) return false;
  if (content.includes(`@${botWxid}`)) return true;
  if (content.includes(` ${botWxid}`)) return true;
  return extractAtUserList(content).includes(botWxid);
}

// ============ 群消息清洗 (cleanGroupMessage) ============
// 群里 @ 检测通过后, 清洗 content 让 AI 看到干净正文 (去 wxid_xxx:\n sender 前缀 + 去 @bot 提及)。
// 仅清洗给 AI 看的 content, 不动 DB 落库 (持久化路径保持原始)。

import { stripGroupContentPrefix } from "../../send/quote-reply.js";

/**
 * 群消息清洗: 去 sender 前缀 (wxid_xxx:\n) + 去 @bot 提及, 让 AI 看干净正文
 *
 * @example
 *   cleanGroupMessage("wxid_sender:\n@bot 你好", "wxid_demo") // → "你好"
 *   cleanGroupMessage("wxid_xxx:\n@bot @所有人 开会", "wxid_demo")     // → "@所有人 开会" (只去 @bot)
 *   cleanGroupMessage("普通消息", "wxid_demo")                            // → "普通消息"
 */
export function cleanGroupMessage(content: string, botWxid: string | null): string {
  if (!content) return content;
  // 步骤 1: 去 wxid_xxx:\n sender 前缀; 步骤 2: 去 @botwxid 提及
  const noSender = stripGroupContentPrefix(content) ?? content;
  const noAt = stripAtMentions(noSender, botWxid);
  return noAt;
}

// src/inbound/parser/wxid.ts - wxid 校验工具

/** 标准 wxid 形式: `wxid_xxx` 或 `gh_xxx` 或 9+ 位 @chatroom */
export function isValidWxid(s: string | null | undefined): boolean {
  if (!s) return false;
  if (s.startsWith("wxid_") || s.startsWith("gh_")) return true;
  return /^[a-zA-Z][\w-]{6,}$/.test(s);
}

/** chatroom wxid: 通常以 @chatroom 结尾, vendor 早期也有 @@ 前缀 */
export function isGroupWxid(s: string | null | undefined): boolean {
  if (!s) return false;
  return s.endsWith("@chatroom") || s.startsWith("@@") || s.includes("@chatroom");
}

/** @user 提及 validation: 合法 wxid 格式 */
export function isValidAtUser(s: string | null | undefined): boolean {
  if (!s) return false;
  return /^(wxid_|gh_)/.test(s);
}

// src/inbound/enrich.ts - DB 单一入口 (仿 本项目/src/inbound/enrich.ts)
// 关键: webhook / handler 都通过本文件写 DB, 避免 webhook 自己 INSERT + handler 再 UPDATE 的重复修复模式

import { logObj as log, formatErr } from "../core/logger.js";
import { saveMessage } from "../db.js";
import type { WppInboundMessage } from "../types.js";

export interface EnrichResult {
  saved: boolean;
  error?: string;
  record?: Record<string, unknown>;
}

/**
 * Persist inbound message to wpp_messages. Idempotent — same msgId can call twice safely.
 * 关键: 不抛, 吞错返 saved:false (silent killer 永久救回靠 caller log)
 */
export async function enrichAndSaveMessage(
  msg: WppInboundMessage,
): Promise<EnrichResult> {
  try {
    await saveMessage({
      account_id: msg.accountId,
      msg_id: msg.msgId,
      new_msg_id: msg.newMsgId,
      // v1.3.21 REVOKE-FIX: 用 msg.direction (outgoing 图片 = outbound), 默认 inbound
      direction: msg.direction ?? "inbound",
      peer_kind: msg.peerKind,
      peer_id: msg.peerId,
      peer_name: msg.fromNickname,
      chat_id: msg.chatroomId,
      msg_type: String(msg.msgType),
      content: msg.content,
      raw_payload: msg.raw,
      from_wxid: msg.fromWxid,
      ts: msg.ts,
    });
    return { saved: true };
  } catch (e) {
    log.warn(`enrichAndSaveMessage failed: ${formatErr(e)}`, {
      msgId: msg.msgId,
    });
    return { saved: false, error: (e as Error).message };
  }
}

/** 多个消息批量保存 */
export async function enrichBatch(batch: WppInboundMessage[]): Promise<{
  saved: number;
  failed: number;
}> {
  // P3-2 (2026-08-13 外部审计): 历史跟踪入库 — 每条消息独立落库 (不同 msg_id, INSERT...ON DUPLICATE 幂等),
  //   相互独立无数据依赖 → 顺序 await 改 Promise.all 并发 (enrichAndSaveMessage 内部吞错永不 reject,
  //   一条失败不阻塞其余 + 计数语义与原串行一致)
  const results = await Promise.all(batch.map((msg) => enrichAndSaveMessage(msg)));
  let saved = 0;
  let failed = 0;
  for (const r of results) {
    if (r.saved) saved++;
    else failed++;
  }
  log.info(`enrichBatch: ${saved} saved, ${failed} failed (size=${batch.length})`);
  return { saved, failed };
}

// src/pairing-store.ts - DM 配对码存储 (per-account 隔离)
// v1.2.3 PAIRING: 老板拍板 "配对码能力移植, 不能与多账号冲突"
// 范式: 仿旧版 wechatpadpromax pairing-store.js, 但按 accountId 分文件 → 多账号天然隔离
// 兑换: 用户私聊 /pair <8位码> → redeem 成功 → wxid 写进 accounts/<id>.json allowFrom
// 安全: 码 8 位 (去 I/O/0/1) + TTL 1h + 一次性消耗 (unlink)

import { mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
import { randomBytes } from "node:crypto";
import { dirname, join } from "node:path";
import { homedir } from "node:os";

/** 配对码有效期 (1h, 跟旧版一致) */
export const PAIRING_CODE_TTL_MS = 60 * 60 * 1000;
/** 码字母表 — 去掉易混淆 I/O/0/1 (旧版同款) */
export const CODE_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
/** 码长度 (8 位, 旧版同款) */
export const PAIRING_CODE_LENGTH = 8;

export interface PairingEntry {
  code: string;
  accountId: string;
  createdAt: string;
  expiresAt: string;
}

/** 配对码存储目录 — 每次读 env (测试可 WPP_PAIRING_DIR 覆盖), 默认 ~/.openclaw/credentials/ */
export function getPairingDir(): string {
  return process.env.WPP_PAIRING_DIR || join(homedir(), ".openclaw", "credentials");
}

/**
 * per-account 配对码文件路径 — 关键多账号隔离: 文件名带 accountId, 互不覆盖。
 * 放 credentials/ 而非 accounts/ (listAccountIds 会扫 accounts/*.json 把配对文件当账号注册!)
 */
export function getPairingStorePath(accountId: string): string {
  return join(getPairingDir(), `wechatpadpro-pairing-${accountId}.json`);
}

/** 生成 8 位随机码 (CODE_ALPHABET) */
export function randomCode(length: number = PAIRING_CODE_LENGTH): string {
  const bytes = randomBytes(length);
  let out = "";
  for (let i = 0; i < length; i++) {
    out += CODE_ALPHABET[bytes[i]! % CODE_ALPHABET.length]!;
  }
  return out;
}

/** 归一化配对码: trim + 大写 (用户输入大小写不敏感) */
export function normalizePairCode(code: string): string {
  return String(code ?? "").trim().toUpperCase();
}

/**
 * 从消息 content 提取配对码 — 严格 /pair 前缀格式 (老板拍板, 不误触发)。
 * 必须是消息整体为 `/pair <8位码>` (可带首尾空白), 不接受尾部垃圾/多余参数。
 * @returns 大写 8 位码, 或 null (不是配对消息)
 */
export function extractPairCode(content: string): string | null {
  if (!content || typeof content !== "string") return null;
  const m = content.match(/^\s*\/pair\s+([A-Z2-9]{8})\s*$/i);
  if (!m) return null;
  return m[1]!.toUpperCase();
}

async function ensureDir(dir: string): Promise<void> {
  try {
    await mkdir(dir, { recursive: true });
  } catch {
    /* ignore: 目录已存在或无法创建 (调用方会感知) */
  }
}

async function readJsonFileSafe(filePath: string): Promise<PairingEntry | null> {
  try {
    const raw = await readFile(filePath, "utf8");
    return JSON.parse(raw) as PairingEntry;
  } catch {
    return null;
  }
}

/** 原子写 (tmp + rename), 防崩溃产生半写文件 */
async function writeJsonFileAtomic(filePath: string, value: PairingEntry): Promise<void> {
  await ensureDir(dirname(filePath));
  const tmpPath = `${filePath}.tmp`;
  await writeFile(tmpPath, JSON.stringify(value, null, 2), "utf8");
  await rename(tmpPath, filePath);
}

function isExpired(entry: PairingEntry): boolean {
  if (!entry?.createdAt) return true;
  return Date.now() - new Date(entry.createdAt).getTime() > PAIRING_CODE_TTL_MS;
}

/**
 * 生成配对码 (覆盖旧码) → 存 per-account 文件 → 返回 entry。
 * @param accountId 目标账号 (文件名隔离)
 */
export async function generatePairingCode(accountId: string): Promise<PairingEntry> {
  const now = new Date();
  const expiresAt = new Date(now.getTime() + PAIRING_CODE_TTL_MS);
  const entry: PairingEntry = {
    code: randomCode(),
    accountId,
    createdAt: now.toISOString(),
    expiresAt: expiresAt.toISOString(),
  };
  await writeJsonFileAtomic(getPairingStorePath(accountId), entry);
  return entry;
}

/** 读本账号配对码 (不存在 / 过期 → null) */
export async function readPairingCode(accountId: string): Promise<PairingEntry | null> {
  const entry = await readJsonFileSafe(getPairingStorePath(accountId));
  if (!entry || isExpired(entry)) return null;
  return entry;
}

/**
 * 兑换配对码 — 校验 accountId 匹配 (防跨账号码) + 码正确 + 未过期 → 一次性消耗 (unlink)。
 * @returns { ok: true } 成功; { ok: false, reason } 失败原因
 */
export async function redeemPairingCode(
  code: string,
  accountId: string,
): Promise<{ ok: boolean; reason?: "invalid" | "expired" | "wrong-account" | "not-found" }> {
  const normalizedInput = normalizePairCode(code);
  if (!normalizedInput) return { ok: false, reason: "invalid" };

  const filePath = getPairingStorePath(accountId);
  const entry = await readJsonFileSafe(filePath);
  if (!entry) return { ok: false, reason: "not-found" };
  if (isExpired(entry)) {
    // 过期码清理 (无副作用)
    try { await unlink(filePath); } catch { /* ignore */ }
    return { ok: false, reason: "expired" };
  }
  // 跨账号防护: 文件里 accountId 必须匹配 (文件名已隔离, 双保险)
  if (entry.accountId && entry.accountId !== accountId) {
    return { ok: false, reason: "wrong-account" };
  }
  const normalizedStored = normalizePairCode(entry.code);
  if (normalizedInput !== normalizedStored) {
    return { ok: false, reason: "invalid" };
  }

  // 一次性消耗: unlink (防重放)
  try { await unlink(filePath); } catch { /* ignore */ }
  return { ok: true };
}

// src/inbound/relay.ts - 群接龙 (chat-history) XML 解析
// 关键: vendor 把 chat-history 作为 appmsg type=53 push, 内含 `<recorditem>` 列表
// (v1 教训: title 字段常含字面 `\n` 真 bug, regex [^\n] 只 match 第 1 条)

import { stripGroupPrefix } from "./parser/content.js";

export interface RelayItem {
  /** 第 N 个条目 (1-based) */
  index: number;
  /** 用户 wxid */
  wxid?: string;
  /** 用户昵称 */
  nickname?: string;
  /** 文字内容 (去 emoji 等) */
  text?: string;
  /** 时间戳 (如有) */
  ts?: number;
}

export interface RelayParseResult {
  title: string;
  items: RelayItem[];
}

/**
 * v1.3.54 RELAY-TRIGGER (2026-08-12 接总立): 识别接龙消息。
 *
 * 真实 vendor 接龙推送 (v1 schema) 是 **type=49 (app, category=app_message)**, title/content 以 "#接龙" 开头;
 * handler 之前只判断 `msgType === 53` (describeMsgType 映射的 chat-history) → 从未匹配 → 接龙不解析、不触发 AI。
 * (v1.3.37 RELAY-PARSE 测试用的 53 是假设, 跟真实 vendor 数据不符 — 集成 bug)
 *
 * 识别:
 *   - msgType===53 (旧 chat-history, 兼容历史)
 *   - msgType===49 && (content/title 含 "#接龙" 或 "接龙" + 编号条目)
 */
export function isRelayMessage(m: { msgType?: number; content?: string; raw?: unknown }): boolean {
  if (m.msgType === 53) return true; // 旧 chat-history (历史兼容)
  if (m.msgType !== 49) return false; // 非 app → 非接龙
  const rawApp = (m.raw as { app?: { title?: unknown } } | undefined)?.app;
  const rawTitle = typeof rawApp?.title === "string" ? rawApp.title : "";
  const text = `${m.content ?? ""} ${rawTitle}`;
  // 微信接龙模板以 "#接龙" 开头; 兼容 "接龙" + 编号条目 (N. xxx) 变体
  return text.includes("#接龙") || (text.includes("接龙") && /(?:^|\n)\s*\d+\.\s/.test(text));
}

/**
 * 解析 vendor 推送的 chat-history/接龙 msg body.
 *
 * 重要: title 字面 `\n` (`\<0x5c><0x6e>`) 不是真换行 — 解析前先 `.replace(/\\n/g, "\n")`.
 * 否则 regex `[^\n]` 只 match 第 1 条 → items.length=1 真 bug
 */
export function parseRelayText(raw: string): RelayParseResult {
  const text = raw.replace(/\\n/g, "\n").replace(/\r\n/g, "\n");

  // 提取 title (chat-history / 接龙)
  // vendor 二进制实测 title 块形如 `<title>...</title>` 或裸字符串
  const titleMatch = text.match(/<title>([\s\S]*?)<\/title>/);
  const titleRaw = titleMatch?.[1] ?? "";
  const title = stripGroupPrefix(titleRaw).trim();
  // v1.3.57 (2026-08-13): 无 <title> 标签时 (真实接龙 type=49 常无), 用 "#接龙 xxx" 首行作 title —
  //   否则所有接龙 title 为空 → 接龙节流 key 相同 → 不同接龙互相节流
  const titleWithFallback = title || text.split("\n")[0]?.trim() || "";

  // 列表条目 — vendor push 用 `<recorditem>` 块或裸 `\n<index>. <nickname>: <text>`
  // 实测: vendor binary 不一定写 <recorditem>, 而是直接 `<index>. <text>` per line
  const recordBlocks = text.match(/<recorditem>[\s\S]*?<\/recorditem>/g);
  let items: RelayItem[] = [];
  if (recordBlocks && recordBlocks.length > 0) {
    items = recordBlocks.map(parseRecordItem);
  } else {
    items = parsePlainList(text);
  }

  return { title: titleWithFallback, items };
}

function parseRecordItem(block: string, idx: number): RelayItem {
  const wxid = block.match(/<username>([\s\S]*?)<\/username>/)?.[1]?.trim();
  const nickname = block.match(/<nickname>([\s\S]*?)<\/nickname>/)?.[1]?.trim();
  const text = block.match(/<text>([\s\S]*?)<\/text>/)?.[1]?.trim();
  return { index: idx + 1, wxid, nickname, text };
}

/**
 * v2026-08-14 10:45 fix (老板 query): 兼容 vendor push 单行无换行接龙.
 * 实测: vendor 把整条接龙 title + 规则 + 接龙者 拼成 1 行字符串, 没有 \n.
 * 例: "#接龙 🎯🎯🎯 ... ㊗益融8月大卖...🥳 1. 门店＋型号 2. 金源北路GT7蓝 倪彩霞"
 * → 直接按 \d+\. 切, 拿到 ["1. 门店＋型号 ", "2. 金源北路GT7蓝 倪彩霞"]
 *   (按老板 6-09 / 8-12 指正: 不假设首词=昵称, 整段给 AI 自己判断)
 */
/** P2-3: 剥掉首个 \d+\.\s 之前的接龙前缀 ("#接龙 xxx 3. 周年庆 ...") — 回退用 */
function stripTitlePrefix(text: string): string {
  const idx = text.search(/\d+\.\s/);
  return idx > 0 ? text.slice(idx) : text;
}

function parsePlainListSingleLine(text: string): RelayItem[] {
  // v1.3.63 P2-3 (2026-08-14 审阅): title 里可能含 "N. " (如 "#接龙 3. 周年庆 1. 门店＋型号 2. ...")
  //   → 不剥前缀会把 "3. 周年庆" 误判成条目且序号乱。策略:
  //     条目总是从 `1. ` 开始 → 从第一个 `1. ` 处切起 (title 里即使有 "3. 周年庆" 也在 1. 之前被弃)
  //     无 `1. ` 时回退: 剥掉首个 \d+\.\s 之前的接龙前缀再切。
  const oneIdx = text.search(/(?:^|\s)1\.\s/);
  const body = oneIdx >= 0 ? text.slice(oneIdx).replace(/^\s+/, "") : stripTitlePrefix(text);
  const chunks = body.split(/(?=\d+\.\s)/).filter((c) => /^\d+\.\s/.test(c.trim()));
  return chunks
    .map((chunk, i): RelayItem | null => {
      const m = chunk.trim().match(/^(\d+)\.\s*(.*)$/);
      if (!m) return null;
      const [, idxStr, rest] = m;
      return {
        index: Number(idxStr ?? i + 1),
        text: rest?.trim() || undefined,
      };
    })
    .filter((x): x is RelayItem => x !== null);
}

function parsePlainList(text: string): RelayItem[] {
  // 统一处理: 先按 \n 分行, 非 "N." 开头的行合并到上一条 (条目内换行延续, 如 "2. 倪彩霞\ngt7")
  //   再按 `\d+\.` 切分成条目 (支持单行 "1. 2. 倪彩霞 gt7 3. ..." 和无换行混合)
  //
  // v2026-08-14 10:45 fix (老板 query, per 6-09 教训回归): vendor push 接龙内容**单行无换行**,
  //   原代码 `text.split(/\n+/)` 只返回 1 个 line, 后续 for loop 因 line 不以 \d+. 开头被跳过,
  //   merged 永远是空 → items=[]. 修法: line 单一时直接走 regex split, 不依赖 \n.
  const lines = text.split(/\n+/).map((l) => l.trim()).filter(Boolean);
  // 合并: 不以 \d+. 开头的行 → 追加到上一条 (条目内换行)
  const merged: string[] = [];
  if (lines.length === 1) {
    // 单行无换行 (vendor push 真实格式): 直接按 \d+\. 切, 不依赖 \n 分行
    return parsePlainListSingleLine(lines[0]!);
  }
  for (const line of lines) {
    if (/^\d+\.\s/.test(line)) {
      merged.push(line);
    } else if (merged.length > 0) {
      merged[merged.length - 1] += " " + line;
    } else {
      // 前导描述 (接龙标题等), 忽略
    }
  }
  // 按 `\d+\.` 切分 (支持单行多条 + 已合并的多行)
  const chunks = merged.join("\n").split(/(?=\d+\.\s)/).filter((c) => /^\d+\.\s/.test(c.trim()));
  return chunks
    .map((chunk, i): RelayItem | null => {
      const m = chunk.trim().match(/^(\d+)\.\s*(.*)$/);
      if (!m) return null;
      const [, idxStr, rest] = m;
      // 保守解析: 只按序号切开, 整段保留原文 (老板 2026-08-11 指正:
      //   接龙用户可改/删昵称, 不能假设首词=昵称 — 让 AI 从上下文理解)
      return {
        index: Number(idxStr ?? i + 1),
        text: rest?.trim() || undefined,
      };
    })
    .filter((x): x is RelayItem => x !== null);
}

// src/inbound/parser/content.ts - 按 msgType 提取 content 文本

import type { MsgTypeValue } from "../../core/constants.js";
import { safeMatch, isCatastrophicRegex } from "../../core/safe-regex.js";

/** 群消息 group prefix 剥离: ":\n<sender nickname>:\n<content>" → "<content>" */
export function stripGroupPrefix(content: string): string {
  if (!content) return "";
  // 用 safeMatch 截断防 ReDoS (原 regex 含嵌套排除类, 极端输入 O(n²) — gewe 实测 1000 字符 hang)
  const re = /^[^:\n]+:\n[^:\n]+:\n([\s\S]*)$/;
  if (isCatastrophicRegex(re)) return content; // 防御性 fallback
  const m = safeMatch(re, content);
  if (m && m[1]) return m[1].trim();
  return content;
}

/** Vendor 消息 type 数字 → human-readable */
export function describeMsgType(msgType: number): string {
  const map: Record<number, string> = {
    1: "text",
    3: "image",
    6: "file", // Excel/PDF/Word/zip 等办公文件
    34: "voice",
    43: "video",
    47: "emoji",
    42: "card",
    48: "location",
    49: "app",
    51: "relay", // 群接龙
    53: "chat-history", // 历史教训: 实际是 53 不是 51
    10000: "system",
    10002: "revoke",
  };
  return map[msgType] ?? `unknown(${msgType})`;
}

/** 强制类型: 仅作为 util */
export type _MsgTypeKey = MsgTypeValue;

// src/inbound/hongbao.ts - 红包 (red packet) 检测 + 业务逻辑
// 红包消息有特定 msgType (appmsg subtype) 或 content 含特定 marker; 提供 detect + 处理建议 (不自动拆)

import { warn, info, formatErr } from "../core/logger.js";
import type { WppInboundMessage } from "../types.js";

/**
 * 检测消息是否是红包
 * - msgType 包含 "hongbao" / "redpacket" (vendor-specific)
 * - content 含 "红包" 关键字 (heuristic, 可能误判但够安全)
 * - raw.appmsg.type === 2002 (微信原生 red packet type)
 */
export function isRedPacketMessage(msg: WppInboundMessage): boolean {
  // heuristic 1: content 含 "红包" 关键字
  if (typeof msg.content === "string" && /红包|red.?packet/i.test(msg.content)) {
    return true;
  }
  // heuristic 2: raw.appmsg.type === 2002 (微信 native red packet)
  const appMsg = (msg.raw as Record<string, unknown>).appMsg as Record<string, unknown> | undefined;
  if (appMsg && (appMsg.type === 2002 || appMsg.type === "2002")) {
    return true;
  }
  // heuristic 3: raw.type 含 "hongbao" (vendor 私有)
  if (typeof (msg.raw as Record<string, unknown>).type === "string") {
    const t = (msg.raw as Record<string, unknown>).type as string;
    if (/hongbao|redpacket/i.test(t)) return true;
  }
  // v1.3.72 转账/支付通知 (v1 schema: app.category === "payment_notice", 如 "收到转账10.00元") 也静默 (老板 2026-08-20)
  //   转账与红包同属支付类 app 消息, 推送简化无 transFerId/transactionId, 不触发 AI 回复
  const app = (msg.raw as Record<string, unknown>).app as Record<string, unknown> | undefined;
  if (app && typeof app.category === "string") {
    if (/payment_notice|transfer|pay/i.test(app.category)) return true;
    if (typeof app.description === "string" && /转账|收款|transfer/i.test(app.description)) return true;
  }
  return false;
}

/**
 * 红包处理结果 (供 inbound/handler 决定下一步)
 */
export interface RedPacketProcessResult {
  /** 红包 URL (用于 OpenHongBao 端点) */
  url?: string;
  /** 红包 key (用于 OpenHongBao 端点) */
  key?: string;
  /** 是否要自动拆 (false = 仅 log) */
  shouldOpen: boolean;
}

/**
 * 从 raw payload 提取红包信息 (url + key for OpenHongBao)
 * vendor 推送时, 红包信息可能在 raw.hongbao / raw.appmsg.hongbaoInfo
 */
export function extractRedPacketInfo(msg: WppInboundMessage): RedPacketProcessResult {
  const raw = msg.raw as Record<string, unknown>;
  // 路径 1: raw.hongbao.url + raw.hongbao.key
  const hb = raw.hongbao as Record<string, unknown> | undefined;
  if (hb && typeof hb.url === "string" && typeof hb.key === "string") {
    return { url: hb.url as string, key: hb.key as string, shouldOpen: false };
  }
  // 路径 2: raw.appMsg.hongbaoInfo
  const appMsg = raw.appMsg as Record<string, unknown> | undefined;
  if (appMsg) {
    const info = appMsg.hongbaoInfo as Record<string, unknown> | undefined;
    if (info && typeof info.url === "string" && typeof info.key === "string") {
      return { url: info.url as string, key: info.key as string, shouldOpen: false };
    }
  }
  return { shouldOpen: false };
}

/**
 * v1.1.7: 红包消息处理 (handler 调用, 默认仅 log)
 * - 检测到: log + 提取 url/key (供后续业务使用)
 * - 未来可加 shouldOpen 配置 (AI 决策 / 用户配置)
 */
export function processRedPacket(
  msg: WppInboundMessage,
  onExtract?: (result: RedPacketProcessResult) => void | Promise<void>,
): RedPacketProcessResult {
  if (!isRedPacketMessage(msg)) {
    return { shouldOpen: false };
  }
  const result = extractRedPacketInfo(msg);
  info(`red packet detected: account=${msg.accountId} peer=${msg.peerId} url=${result.url ? "present" : "missing"}`);
  if (onExtract) {
    try {
      const r = onExtract(result);
      if (r && typeof (r as Promise<unknown>).then === "function") {
        (r as Promise<unknown>).catch((e) => warn(`redPacket onExtract error: ${formatErr(e)}`));
      }
    } catch (e) {
      warn(`redPacket onExtract sync error: ${formatErr(e)}`);
    }
  }
  return result;
}

// src/inbound/parser.ts - vendor JSON payload → normalized WppInboundMessage

import { PeerKind } from "../core/constants.js";
import type { WppInboundMessage, WppWebhookPayload } from "../types.js";

function num(v: unknown, fallback: number): number {
  if (typeof v === "number") return v;
  if (typeof v === "string") {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  }
  return fallback;
}

function str(v: unknown): string {
  return v == null ? "" : String(v);
}

/**
 * Convert vendor payload (a flat JSON object with various field aliases) to
 * a normalized WppInboundMessage.
 *
 * Vendor field conventions (sampled from swagger.json 2026-08-04):
 *   - fromUser / fromWxid / fromUserName : sender wxid
 *   - fromNick / fromNickname : sender nick
 *   - toWxid / toUserName : receiver (self) wxid
 *   - msgType : numeric (1=text, 3=image, 34=voice, 43=video, 47=emoji)
 *   - content / text / msg : payload body
 *   - msgId : varchar (often 16+ digit integer as string already)
 *   - newMsgId : secondary id
 *   - ts / createTime : epoch seconds (sometimes ms; detect via magnitude)
 *   - chatroomId / roomId : group id (presence implies group message)
 */
export function payloadToInboundMessage(
  accountId: string,
  payload: WppWebhookPayload,
): WppInboundMessage | null {
  try {
    const obj = payload as Record<string, unknown>;

    // vendor 业务回调: { Wxid, EventType, Timestamp, Data: { ..., Data: { AddMsgs: [...] } } }
    // 消息在 AddMsgs[] → 取第一条
    if (obj.EventType === "sync_message" && obj.Data) {
      const dataOuter = obj.Data as Record<string, unknown>;
      const dataInner = dataOuter.Data as Record<string, unknown> | undefined;
      const addMsgs = dataInner?.AddMsgs;
      if (Array.isArray(addMsgs) && addMsgs.length > 0) {
        const msg = addMsgs[0] as Record<string, unknown>;
        const out = parseBusinessCallbackMsg(accountId, msg);
        return out;
      }
      return null; // 无 AddMsgs 不认
    }

    // vendor webhook 推送: 顶层 Wxid + Data 内层消息
    const wrappedData = obj.Data as Record<string, unknown> | undefined;
    const topMsgType = obj.MessageType;
    let src: Record<string, unknown> = obj;
    let msgTypeOverride: unknown;

    if (wrappedData && typeof wrappedData === "object" && !Array.isArray(wrappedData)) {
      const hasMsgField = Object.keys(wrappedData).some((k) =>
        /Content|FromWxid|FromUser|MsgId|MsgType|Text/i.test(k),
      );
      if (hasMsgField) {
        src = wrappedData;
        msgTypeOverride = topMsgType;
      } else {
        return null;
      }
    }

    const fromWxid = str(src.fromUser ?? src.fromWxid ?? src.fromUserName ?? src.FromWxid ?? src.FromUser);
    if (!fromWxid) return null;

    const fromNick = src.fromNick ?? src.fromNickname ?? src.FromNick ?? src.FromNickname;
    const toWxid = src.toWxid ?? src.toUserName ?? src.ToWxid ?? src.ToUserName;
    const chatroomId = src.chatroomId ?? src.roomId ?? src.ChatroomId ?? src.RoomId;
    const chatroomIdStr = chatroomId == null ? undefined : str(chatroomId);

    let msgType = num(src.msgType ?? src.MsgType, 1);
    if (msgTypeOverride !== undefined && msgTypeOverride !== "sync_message") {
      const t = num(msgTypeOverride, msgType);
      if (t !== 1 || msgTypeOverride === "1") msgType = t;
    }
    const content = str(src.content ?? src.text ?? src.msg ?? src.Content ?? src.Text);

    const newMsgId = str(src.newMsgId ?? src.NewMsgId);
    const msgId = str(src.msgId ?? src.MsgId) || newMsgId;

    let ts = num(src.ts ?? src.createTime ?? src.Timestamp ?? src.CreateTime, Date.now() / 1000);
    if (ts > 1e12) ts = Math.floor(ts / 1000);
    ts = Math.floor(ts);

    const peerKind = chatroomIdStr ? PeerKind.GROUP : PeerKind.DIRECT;
    // 群聊 peerId = chatroomId; 私聊先 fallback fromWxid (peerId 方向修正见 handler.ts selfWxid 判断)
    const peerId = chatroomIdStr ?? fromWxid;

    return {
      accountId,
      msgId: msgId || `${ts}-${Math.random().toString(36).slice(2, 10)}`, // 防空 msgId 炸 DB
      newMsgId,
      fromWxid,
      fromNickname: fromNick == null ? undefined : str(fromNick),
      chatroomId: chatroomIdStr,
      toWxid: toWxid == null ? undefined : str(toWxid),
      msgType,
      content,
      ts,
      raw: payload,
      peerKind,
      peerId,
      trigger: "direct", // 后续 inbound/handler.ts 触发器模块覆盖
    };
  } catch {
    return null;
  }
}

/** Backward-compat alias */
export const parseInbound = payloadToInboundMessage;

/**
 * 解析 vendor v1 消息格式 (schema=wechatpad.message.v1):
 *   { content, conversation_id, created_at, direction, id, is_group, kind,
 *     local_id, recipient_id, sender_id, status, type }
 * 过滤规则 (只保留可交互入站): 非 incoming / kind=status / sender_id 以 gh_ 开头 / type=51 → null
 */
function parseV1Message(
  accountId: string,
  msg: Record<string, unknown>,
): WppInboundMessage | null {
  const str2 = (v: unknown): string | undefined => {
    if (v == null) return undefined;
    return typeof v === "string" ? v : String(v);
  };

  const senderId = str2(msg.sender_id) ?? "";
  const recipientId = str2(msg.recipient_id);
  const direction = str2(msg.direction);
  /** filehelper 会话识别 (conversation_id 或 recipient_id = filehelper) */
  const conversationIdOrFileHelper = (m: Record<string, unknown>): string | undefined =>
    str2(m.conversation_id) ?? recipientId;
  const kind = str2(msg.kind);
  const msgType = num(msg.type, 1);
  const content = str2(msg.content) ?? "";
  const rawMsgId = str2(msg.id) ?? "";
  const v1NewMsgId = str2(msg.new_msg_id) ?? str2(msg.svr_id) ?? "";
  const createdAt = num(msg.created_at, Date.now() / 1000);

  // 过滤: 非入站 / 系统状态 / 公众号 / 系统操作
  // v1.3.21 REVOKE-FIX (2026-08-10): 放行 outgoing 图片 (kind=image / msgType=3) —
  //   插件自己发的图片, vendor 会推送回 WPP (business callback), 过滤掉就拿不到真实 server ID,
  //   图片撤回需要它 (UploadImg 返回的 Newmsgid 是上传凭证, 非 server 消息 ID)。
  //   其它 outgoing (文本/语音/视频) 仍过滤 (AI 回复进上下文会混乱)。
  const isOutgoingImage =
    direction && direction !== "incoming" && (kind === "image" || msgType === 3);
  // v1.3.39 FILEHELPER (老板 2026-08-11): filehelper 只放行**命令** (非命令仍过滤)
  //   老板在机器人手机的文件传输助手里发命令 (/genpair 等) → 放行; 普通消息不放行 (不进 AI)
  const isFileHelper = recipientId === "filehelper" || conversationIdOrFileHelper(msg) === "filehelper";
  const isFileHelperCommand = isFileHelper && /^\s*\//.test(content);
  if (direction && direction !== "incoming" && !isOutgoingImage && !isFileHelperCommand) return null;
  if (kind === "status") return null;
  if (!senderId) return null;
  if (senderId.startsWith("gh_")) return null;
  if (msgType === 51) return null;

  // 群聊必须按 groupId 建 session (否则按人拆, 群上下文串台): 优先级 conversation_id > recipient_id > sender_id
  const conversationId = str2(msg.conversation_id);
  const groupCandidates = [conversationId, recipientId, senderId].filter((v): v is string => typeof v === "string" && v.endsWith("@chatroom"));
  const chatroomWxid = groupCandidates[0];
  const isGroup = msg.is_group === true || chatroomWxid !== undefined;
  const peerKind = isGroup ? PeerKind.GROUP : PeerKind.DIRECT;
  // v1.3.39 FILEHELPER: filehelper 特殊会话 peerId=filehelper (命令处理识别用)
  //   (senderId 是机器人自己, 若用 senderId 作 peerId 会无法识别 filehelper 会话)
  const isFileHelperPeer = conversationId === "filehelper" || recipientId === "filehelper";
  // 群聊 peerId=groupId; 私聊先 fallback senderId (方向修正见 handler.ts selfWxid 判断)
  const peerId = chatroomWxid ?? (isFileHelperPeer ? "filehelper" : senderId);
  const ts = Math.floor(createdAt);

  // content 是 XML 时保留原文 (上层 quoteBot / XML 解析处理)
  return {
    accountId,
    msgId: rawMsgId || `${ts}-${Math.random().toString(36).slice(2, 10)}`,
    newMsgId: v1NewMsgId,
    fromWxid: senderId,
    fromNickname: undefined,
    chatroomId: chatroomWxid,
    toWxid: recipientId,
    msgType,
    content,
    ts,
    raw: msg as unknown as WppWebhookPayload,
    peerKind,
    peerId,
    // v1.3.21 REVOKE-FIX: 透传 direction (outgoing 图片需标 outbound, enrich 入库方向才正确)
    direction: direction === "incoming" ? ("inbound" as const) : ("outbound" as const),
    trigger: "direct",
  };
}

export function payloadToAllInboundMessages(
  accountId: string,
  payload: WppWebhookPayload,
): WppInboundMessage[] {
  try {
    const obj = payload as Record<string, unknown>;
    // 业务回调逐条 parse, 支持两种 vendor 格式: v1 Data.messages[] / 旧 Data.Data.AddMsgs[]
    if (obj.EventType === "sync_message" && obj.Data) {
      const dataOuter = obj.Data as Record<string, unknown>;
      const out: WppInboundMessage[] = [];

      // v1 格式: Data.messages[] (wechatpad.message.v1 schema)
      const messages = dataOuter.messages;
      if (Array.isArray(messages)) {
        for (const item of messages) {
          const m = parseV1Message(accountId, item as Record<string, unknown>);
          if (m) out.push(m);
        }
        return out;
      }

      // 旧格式: Data.Data.AddMsgs[]
      const dataInner = dataOuter.Data as Record<string, unknown> | undefined;
      const addMsgs = dataInner?.AddMsgs;
      if (Array.isArray(addMsgs) && addMsgs.length > 0) {
        for (const item of addMsgs) {
          const m = parseBusinessCallbackMsg(accountId, item as Record<string, unknown>);
          if (m) out.push(m);
        }
        return out;
      }
      return [];
    }
    // 其他格式走原 parser (取一条)
    const single = payloadToInboundMessage(accountId, payload);
    return single ? [single] : [];
  } catch {
    return [];
  }
}

/**
 * 解析 vendor business callback 单条消息
 * vendor 字段都是 {string: "..."} 包装 (内部 JSON 序列化); MsgType=1 纯文本, 其他是 XML
 *   - FromUserName/ToUserName/Content → 解包 {string: ...} 为字符串
 *   - NewMsgId 大整数 (注意精度)
 *   - 群聊识别: FromUserName/ToUserName 结尾 "@chatroom"
 */
function parseBusinessCallbackMsg(
  accountId: string,
  msg: Record<string, unknown>,
): WppInboundMessage | null {
  // 解包 vendor {string: "..."} 包装
  const unwrap = (v: unknown): string | undefined => {
    if (v == null) return undefined;
    if (typeof v === "string") return v;
    if (typeof v === "object" && v !== null && "string" in v) {
      return str((v as Record<string, unknown>).string);
    }
    return str(v);
  };

  const fromWxid = unwrap(msg.FromUserName) ?? "";
  const toWxid = unwrap(msg.ToUserName);
  const rawContent = unwrap(msg.Content) ?? "";
  const msgType = num(msg.MsgType, 1);
  const createTime = num(msg.CreateTime, Date.now() / 1000);
  const msgId = str(msg.MsgId);
  const newMsgId = str(msg.NewMsgId);

  if (!fromWxid) return null;

  // 群聊识别: FromUserName 或 ToUserName 结尾是 "@chatroom"
  const isGroup = (fromWxid?.endsWith("@chatroom") ?? false) || (toWxid?.endsWith("@chatroom") ?? false);
  const chatroomWxid = fromWxid?.endsWith("@chatroom") ? fromWxid : (toWxid?.endsWith("@chatroom") ? toWxid : undefined);
  const peerKind = isGroup ? PeerKind.GROUP : PeerKind.DIRECT;
  const peerId = isGroup ? (chatroomWxid ?? fromWxid) : fromWxid;

  // Content 处理: MsgType=1 纯文本, MsgType=51/47/etc 是 XML
  // 业务回调直接保留原文 (后续 dispatcher 根据 msgType 处理 XML / 提取文本)
  const content = rawContent;

  return {
    accountId,
    msgId: msgId || newMsgId || `${createTime}-${Math.random().toString(36).slice(2, 10)}`,
    newMsgId,
    fromWxid,
    fromNickname: undefined, // business callback 未提供 nickname
    chatroomId: isGroup ? chatroomWxid : undefined,
    toWxid: toWxid,
    msgType,
    content,
    ts: Math.floor(createTime),
    raw: msg,
    peerKind,
    peerId,
    trigger: "direct", // 后续 handler 触发器模块覆盖
  };
}

// webhook-receiver.ts - HTTP webhook 接收 vendor 回调
// 安全: 10MB body 硬 cap (防内存 DoS) + 30s 超时 (防 slow client) + 可选 HMAC-SHA256 签名验证

import { createServer, type Server } from "node:http";
import { logObj as log, formatErr } from "./core/logger.js";
import { WEBHOOK_BODY_LIMIT_BYTES, REQUEST_TIMEOUT_MS } from "./core/constants.js";
import {
  verifyHmacSha256,
  signatureRequired,
  extractSignatureHeader,
} from "./core/signature.js";
import { WebhookMetrics } from "./monitor/metrics.js";
import { parseJsonText } from "./api/client.js";
import type { WppWebhookPayload, WppWebhookServer } from "./types.js";

export class WechatpadproWebhookServer implements WppWebhookServer {
  private server: Server | null = null;
  /** 可选 body limit override (测试用, 默认 10MB) */
  private bodyLimitBytes: number;

  constructor(
    private host: string,
    private port: number,
    /**
     * 多路径 + 每路径独立 handler (同步消息走 webhook 路径, 完整业务回调走 business 路径)
     */
    private paths: Array<{ path: string; onMessage: (payload: WppWebhookPayload) => void | Promise<void> }>,
    private secret?: string, // 可选 secret, 配了则启用 signature 验证
    opts?: { bodyLimitBytes?: number; requestTimeoutMs?: number },
  ) {
    this.bodyLimitBytes = opts?.bodyLimitBytes ?? WEBHOOK_BODY_LIMIT_BYTES;
    // 注: timeout 暂用全局 REQUEST_TIMEOUT_MS, 暂不开放 override
  }

  /**
   * v1.3.61 WEBHOOK-SHARED-PORT: 动态注册 path (多账号共享端口, 单 server 实例多 path)。
   * 幂等: 同 path 已存在则跳过。start 前后均可调用 (start 后注册的 path 立即生效, 因 handler 实时查 this.paths)。
   */
  addPath(path: string, onMessage: (payload: WppWebhookPayload) => void | Promise<void>): void {
    if (this.paths.some((p) => p.path === path)) return;
    this.paths.push({ path, onMessage });
    log.info(`[WPP v1.3.61] webhook addPath: ${path} (total ${this.paths.length})`);
  }

  /**
   * v1.3.63 P1 (2026-08-14 审阅): 移除账号时清理 path (防 zombie handler)。
   * 幂等: path 不存在则 no-op。共享 server 多账号场景下, 单账号移除只 removePath 不 stop server。
   */
  removePath(path: string): void {
    const before = this.paths.length;
    this.paths = this.paths.filter((p) => p.path !== path);
    if (this.paths.length !== before) {
      log.info(`[WPP v1.3.63] webhook removePath: ${path} (total ${this.paths.length})`);
    }
  }

  async start(): Promise<void> {
    return new Promise((resolve, reject) => {
      this.server = createServer((req, res) => {
        WebhookMetrics.incReceived();

        // 请求级 timeout 防 slow client DoS
        req.setTimeout(REQUEST_TIMEOUT_MS, () => {
          if (!res.headersSent) {
            res.statusCode = 408;
            res.end("request timeout");
            WebhookMetrics.incRejectedTimeout?.();
          }
        });

        if (req.method !== "POST") {
          WebhookMetrics.incRejectedPath();
          res.statusCode = 404;
          res.end("not found");
          return;
        }
        // 按 url 查匹配 handler
        const matched = this.paths.find((p) => p.path === req.url);
        if (!matched) {
          WebhookMetrics.incRejectedPath();
          res.statusCode = 404;
          res.end("not found");
          return;
        }
        const onMessage = matched.onMessage;
        const matchPath = matched.path;

        // 收集 body (验签要用 raw body, 不能用 parsed JSON)
        // 累计 size 防 memory DoS (chunk 总和 > 10MB → 413)
        const chunks: Buffer[] = [];
        let totalSize = 0;
        let bodyTooLarge = false;
        let bodyAborted = false;
        const bodyLimit = this.bodyLimitBytes;
        req.on("data", (chunk: Buffer) => {
          if (bodyAborted || bodyTooLarge) return;
          totalSize += chunk.length;
          if (totalSize > bodyLimit) {
            bodyTooLarge = true;
            WebhookMetrics.incRejectedBodySize?.();
            if (!res.headersSent) {
              res.statusCode = 413;
              res.end("payload too large");
            }
            req.destroy();
            return;
          }
          chunks.push(chunk);
        });
        req.on("aborted", () => {
          bodyAborted = true;
        });

        req.on("end", async () => {
          if (bodyAborted) {
            if (!res.headersSent) {
              res.statusCode = 400;
              res.end("request aborted");
            }
            return;
          }
          if (bodyTooLarge) return; // 已在 data handler 返 413
          const rawBody = Buffer.concat(chunks);

          // signature 验证: HMAC-SHA256 (等 vendor 公开算法)
          if (signatureRequired(this.secret)) {
            const sig = extractSignatureHeader(req.headers as Record<string, string | string[] | undefined>);
            if (!verifyHmacSha256(rawBody, sig, this.secret!)) {
              log.warn(
                `webhook signature verify failed: account=${matchPath} ` +
                  `(signature=${sig ? "present" : "missing"})`,
              );
              WebhookMetrics.incRejectedSignature?.();
              res.statusCode = 401;
              res.end("unauthorized");
              return;
            }
            log.debug(`webhook signature ok: path=${matchPath}`);
          }
          // secret 没配 → 接受 (vendor 当前不签)

          // Parse + dispatch
          // v1.3.18 F6 fix: 用 parseJsonText 预引号化 16+ 位大整数 (msg_id/new_msg_id 防丢精度)
          let payload: WppWebhookPayload;
          try {
            payload = parseJsonText(rawBody.toString("utf8")) as WppWebhookPayload;
            if (!payload) throw new Error("parseJsonText returned null");
          } catch (e) {
            // formatErr 保留 stack
            log.warn(`webhook parse error: ${formatErr(e)}`);
            WebhookMetrics.incRejectedParse?.();
            res.statusCode = 400;
            res.end("bad request");
            return;
          }
          try {
            await onMessage(payload);
            WebhookMetrics.incProcessed();
            res.statusCode = 200;
            res.end("ok");
          } catch (e) {
            log.warn(`webhook onMessage error: ${formatErr(e)}`);
            if (!res.headersSent) {
              res.statusCode = 500;
              res.end("server error");
            }
          }
        });

        req.on("error", (e) => {
          log.warn(`webhook req error: ${formatErr(e)}`);
        });
      });
      this.server.once("error", reject);
      this.server.listen(this.port, this.host, () => {
        log.info(
          `webhook server listening: ${this.host}:${this.port}${this.paths.map(p=>p.path).join(",")}` +
            (signatureRequired(this.secret) ? " (signature verification: ON)" : " (signature: OFF, no secret)"),
        );
        resolve();
      });
    });
  }

  async stop(): Promise<void> {
    return new Promise((resolve) => {
      if (!this.server) {
        resolve();
        return;
      }
      const s = this.server;
      // server.close() 会等所有活跃连接关闭 (HTTP keep-alive),
      //   如果 vendor 长连接 or half-closed 客户端挂住 → close() 永不 resolve → 进程退出卡死 →
      //   systemd 重启时新进程 EADDRINUSE 老进程的 port.
      //   fix:
      const safetyTimer = setTimeout(() => {
        log.warn("webhook server stop timeout (3s) - force resolved");
        this.server = null;
        resolve();
      }, 3000);
      safetyTimer.unref?.();
      if (typeof s.closeAllConnections === "function") {
        try { s.closeAllConnections(); } catch { /* ignore */ }
      }
      s.close(() => {
        clearTimeout(safetyTimer);
        log.info("webhook server stopped");
        this.server = null;
        resolve();
      });
    });
  }
}

// ============ dedupe 工具 ============

/** 30 分钟 in-memory dedupe. Export for test introspection. */
export class SeenTracker {
  private readonly map = new Map<string, number>();
  private readonly ttlMs: number;

  constructor(ttlMs: number = 30 * 60 * 1000) {
    this.ttlMs = ttlMs;
  }

  check(key: string, ttlOverride?: number): boolean {
    const ttl = ttlOverride ?? this.ttlMs;
    const now = Date.now();
    const seen = this.map.get(key);
    if (seen !== undefined && now - seen < ttl) return false;
    this.map.set(key, now);
    if (this.map.size > 1000) {
      for (const [k, v] of this.map) {
        if (now - v > ttl) this.map.delete(k);
      }
    }
    return true;
  }
  size(): number {
    return this.map.size;
  }
}

/** Build dedupe key. 优先级: newMsgId > msgId > content-hash, appId 隔离
 * 陷阱 1: 用 `??` 处理空字符串会得到空 key → 所有消息 dedup key 相同 → 消息被静默丢弃, 必须用显式空字符串判断
 * 陷阱 2 (v1.2.1 P1-fix): 两个 id 都缺时塌缩到 "noid" → 不同消息共用同 key → 第二条被误丢。
 *        改为用 content hash 参与, 同一内容在同一账号/会话内收敛到同 key, 不同内容不误丢。
 */
export function buildDedupeKey(
  appId: string | undefined,
  newMsgId: string | undefined,
  msgId: string | undefined,
  content?: string,
): string {
  let idPart =
    newMsgId && newMsgId !== "" ? newMsgId :
    msgId && msgId !== "" ? msgId :
    "";
  if (!idPart) {
    // 两个 id 都缺 → content hash (稳定, 同内容同 key, 不同内容不误丢)
    idPart = content ? `c:${simpleHash(content)}` : "noid";
  }
  return `${appId ?? "noapp"}:${idPart}`;
}

/** 简单字符串哈希 (dedupe content hash 用, 非安全场景) */
function simpleHash(s: string): string {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = (h << 5) - h + s.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(36);
}

// src/core/signature.ts - Webhook 签名验证 (v1.1.1 full mode)
// 范式: 仿 OpenClaw v2026.7.1+ src/core/signature.ts (HMAC + timingSafeEqual + multi-algorithm)
//
// v1.1.1 状态 (2026-08-04):
//   - vendor 暂未公开算法, 但实现支持 sha256 / sha1 / md5 多算法 (兼容主流 webhook)
//   - signatureRequired 改 strict mode (无 secret 也返 true, 强制 webhook 必须配 secret)
//   - extractSignatureHeader 优先 X-Signature, fallback X-Hub-Signature-256, X-WPP-Signature
//
// 调用方约定:
//   - verifySignature(body, signature, secret, opts) - 一站式, 默认 sha256
//   - signatureRequired(secret) - 决定是否验签 (v1.1.1 strict: 永远 true, 业务决定)
//   - extractSignatureHeader(headers) - 多 candidate 提取

import { createHmac, timingSafeEqual } from "node:crypto";

/** 支持的 HMAC 算法 (v1.1.1 多算法) */
export type SignatureAlgorithm = "sha256" | "sha1" | "md5";

const ALGO_PREFIX: Record<SignatureAlgorithm, string> = {
  sha256: "sha256=",
  sha1: "sha1=",
  md5: "md5=",
};


export interface VerifyOpts {
  /** 算法 (默认 sha256, 兼容 GitHub/vendor) */
  algorithm?: SignatureAlgorithm;
  /** 严格模式: signature header 必须存在, 不在直接 false (默认 true) */
  strict?: boolean;
}

/**
 * v1.1.1: 验证 webhook 签名 (多算法支持).
 * 替代 v1.0.1 的 verifyHmacSha256, 默认 sha256 (向后兼容).
 *
 * @param body raw webhook body (Buffer 或 string, 必须是 vendor 签的原内容)
 * @param signature signature header 值 (e.g. "sha256=hex" 或 "sha1=hex" 或纯 hex)
 * @param secret webhook secret (跟 vendor 后台配的一致)
 * @param opts.algorithm 默认 sha256
 * @returns true = 验签通过, false = 失败
 */
export function verifySignature(
  body: string | Buffer,
  signature: string | undefined,
  secret: string,
  opts: VerifyOpts = {},
): boolean {
  const algo: SignatureAlgorithm = opts.algorithm ?? "sha256";

  if (!signature) return false;
  if (!secret) return false;

  let detected: SignatureAlgorithm = algo;
  let sigValue = signature;
  for (const [a, prefix] of Object.entries(ALGO_PREFIX) as [SignatureAlgorithm, string][]) {
    if (signature.startsWith(prefix)) {
      detected = a;
      sigValue = signature.slice(prefix.length);
      break;
    }
  }

  const expectedHex = createHmac(detected, secret).update(body).digest("hex");
  if (sigValue.length !== expectedHex.length) return false;

  try {
    return timingSafeEqual(Buffer.from(sigValue, "hex"), Buffer.from(expectedHex, "hex"));
  } catch {
    return false; // hex 解析失败
  }
}

/**
 * 保持 v1.0.1 API 兼容 (deprecated, v1.2+ 删).
 * @deprecated use verifySignature instead
 */
export function verifyHmacSha256(
  body: string | Buffer,
  signature: string | undefined,
  secret: string,
): boolean {
  return verifySignature(body, signature, secret, { algorithm: "sha256" });
}

/**
 * v1.1.10 P0-3 (2026-08-05 回滚): 是否需要 signature 验证 — 改回 v1.0.1 permissive.
 *
 * 决策: 是否有 secret → 决定是否验签.
 *   - secret 已配 → 返 true (强制 verify, caller 调 verifySignature 验)
 *   - secret 未配 → 返 false (skip 整个 verify 步骤)
 *
 * 历史:
 *   - v1.0.1: 返 !!secret (permissive, 跟 github webhook 行为一致)
 *   - v1.1.1: 改 strict 永远 true (没 secret 也强制 verify) — 这版跟 vendor 不兼容
 *     vendor `/Webhook/Set` (src/send/webhook.ts) 不提供签名字段, 推 webhook 不带 X-Signature 头
 *     → 老板 2026-08-05 21:35 拍的 401 全是 vendor 不签造成的
 *   - v1.1.10: 老板拍改回 permissive. secret 留 / 空由业务方决定.
 *     risk: webhook 公网暴露会被人乱刷, 但 1Panel openresty 反代层已挡 + authcode 路径段当隐式 auth 凑合用.
 *
 * 注: 未来 vendor 真提供签名后再用 v1.1.1 strict 也行 (那时 secret 必须填).
 */
export function signatureRequired(secret: string | undefined): boolean {
  return !!secret;
}

/**
 * 签名 header 候选 (按优先级).
 * OpenClaw 兼容: 优先 X-Signature (vendor 通用), fallback X-Hub-Signature-256 (GitHub), X-WPP-Signature (wpp 私有).
 */
export function extractSignatureHeader(headers: Record<string, string | string[] | undefined>): string | undefined {
  const candidates = [
    headers["x-signature"],
    headers["x-hub-signature-256"],
    headers["x-wpp-signature"],
  ];
  for (const c of candidates) {
    if (typeof c === "string" && c.length > 0) return c;
    if (Array.isArray(c) && c.length > 0 && typeof c[0] === "string") return c[0];
  }
  return undefined;
}

// src/monitor/metrics.ts - Prometheus counters (wechatpadpro_*)
// 范式仿 本项目/src/monitor/metrics.ts

const counters = new Map<string, number>();

/** Counter namespacing: wpp_messages_received_total etc. */
const ns = "wpp";

/** 增 1 (default) 或增 n */
export function incCounter(name: string, n = 1): void {
  const k = `${ns}_${name}`;
  counters.set(k, (counters.get(k) ?? 0) + n);
}

/** 读 (测试/debug 用) */
export function getCounter(name: string): number {
  return counters.get(`${ns}_${name}`) ?? 0;
}

/** 重置 (测试/teardown 用) */
export function resetAllCounters(): void {
  counters.clear();
}

/** 输出 Prometheus 0.0.4 text format */
export function renderPrometheus(): string {
  const lines: string[] = [];
  const byType = new Map<string, string[]>();
  for (const k of counters.keys()) {
    const [type, ...rest] = k.split("_");
    if (!type) continue;
    const restStr = rest.join("_");
    if (restStr === undefined) continue;
    const base = restStr.replace(/_total$/, "");
    if (!byType.has(type)) byType.set(type, []);
    byType.get(type)!.push(base);
  }
  for (const [type, names] of byType) {
    for (const n of names) {
      lines.push(`# TYPE ${ns}_${type}_${n} counter`);
      lines.push(`${ns}_${type}_${n}_total ${counters.get(`${ns}_${type}_${n}_total`) ?? 0}`);
    }
  }
  return lines.join("\n") + "\n";
}

